["loc_vit_88_01"] = "GÜVENLİĞİ ARTIRMIŞLAR GALİBA. OVAL OFİSİ DAĞITMADAN KEPENKLERİ AÇMANIN BİR YOLUNU BULMALIYIZ.",
["loc_vit_89_01"] = "SİZE MALZEME GETİREMEM. ŞÜPHELENİP BENİ VURURLAR. BEN BİR ŞEY DÜŞÜNÜRKEN ETRAFA BAKIN.",
["loc_vit_89_02"] = "HELİKOPTERDEN SİZE DAHA FAZLA MALZEME GÖNDERMENİN YOLU YOK. ORADA BULDUKLARINIZLA İDARE ETMELİSİNİZ. BEN SİZİ GEÇİRMEYE ÇALIŞIRKEN SİZ ETRAFA BAKIN.",
["loc_vit_89_03"] = "BEN BU KONUDA NE YAPABİLECEĞİMİZE BAKARKEN ETRAFTA İŞE YARAR BİR ŞEY ARAYIN.",
["loc_vit_90_01"] = "TAMAM, ALDIĞIM İSTİHBARATA GÖRE ORALARDA BİR YERDE TERMİT SAKLANIYOR OLABİLİR. ARAMAYA BAŞLAYIN. BULUNCA BARİYERİN ÜSTÜNE KOYUN.",
["loc_vit_90_02"] = "İSTİHBARATA GÖRE ORALARDA BİR YERE TEHLİKELİ KİMYASALLAR YIĞMIŞLAR. O ENGELDE KULLANABİLECEĞİNİZ NE VAR BAKIN, TAMAM MI?",
["loc_vit_91_01"] = "BARİYERDE KULLANABİLECEĞİNİZ GÜÇLÜ BİR ŞEY İÇİN BATI KANADINI ARAYIN!",
["loc_vit_91_02"] = "SAĞLAM BİR ŞEY ARAMAYA DEVAM EDİN; O ENGELİ AŞMALISINIZ!",
["loc_vit_91_03"] = "ORALARDA KULLANABİLECEĞİNİZ PATLAYICI BİR ŞEY MUTLAKA VARDIR!",
["loc_vit_92_01"] = "TAMAM, ŞİMDİ BULDUĞUNUZ TERMİTİ O KEPENKLERDE KULLANIN.",
["loc_vit_92_02"] = "O KEPENKLER TERMİTE DAYANAMAZ. ÜSTLERİNE BİRAZ KOYUN!",
["loc_vit_92_03"] = "BULDUĞUNUZ TERMİTLE KEPENKLERİ ERİTMELİSİNİZ, TAMAM MI?",
["loc_vit_93_01"] = "NEYİ BEKLİYORSUNUZ, TERMİTİ KULLANIN!",
["loc_vit_93_02"] = "TERMİT DOSTLAR! ENGELİN ÜZERİNE KOYUN.",
["loc_vit_93_03"] = "TERMİTİ ENGELDE KULLANMALISINIZ.",
["loc_vit_94_01"] = "TERMİT YAKIP GEÇTİ, İÇERİ GİRİN.",
["loc_vit_94_02"] = "TERMİTİN ÇALIŞMASINI İZLEMEK HER ZAMAN BİR ZEVK! ŞİMDİ İÇERİ GİRİN.",
["loc_vit_94_03"] = "GÜZEL. DOĞRUCA YEDİ GEÇTİ. ŞİMDİ İÇERİ GİRİN!",
