["loc_vit_97_01"] = "AH, ŞU MARK II KASA MODELLERİNDEN BİRİ. İÇİNDEKİLERİ YOK ETMEDEN PATLATAMAYIZ.",
["loc_vit_97_02"] = "AH, BİR JÄGER MARK II... İÇİNDEKİLERİ YOK ETMEDEN AÇMAK ZORDUR.",
