["loc_vit_98_03"] = "GEÇMEK İÇİN SİZİNLE GÖNDERDİĞİM DEĞİŞTİRİLMİŞ MATKABI KULLANABİLİRSİNİZ. ",
["loc_vit_99_01"] = "AMA ÇOK ELEKTRİK HARCIYOR, BİR YERE BAĞLAMANIZ GEREK.",
