["loc_vit_99_03"] = "PRİZDEN BİRAZ ELEKTRİK VERMENİZ GEREKECEK.",
["loc_vit_brf_01"] = "İŞTE BAŞLIYORUZ SEVGİLİ DOSTLAR. ARADIĞIMIZ AF BELGELERİ BÜYÜK İHTİMALLE BEYAZ SARAY'IN ALTINDAKİ BAŞKANLIK ACİL DURUM OPERASYON MERKEZİ'NDE, YANİ PEOC'TA TUTULUYOR. KESİN AYRINTILARI ALAMADIM. GÜVENLİĞİ CİDDİ BİÇİMDE ARTIRMIŞLAR GİBİ, DURUMA GÖRE HAREKET ETMELİYİZ. SİZİ BİZZAT BEN UÇURACAĞIM. BİRAZ ARALARINA KARIŞABİLMENİZ İÇİN MURKY ÜNİFORMALARI GİYECEKSİNİZ. MÜMKÜNSE SESSİZCE GİRİN, GERÇEKTEN GEREKİRSE GÜRÜLTÜ KOPARIN. BU BAIN İÇİN. BELKİ BİZİM İÇİN DE, HA?",
["loc_vit_cnc_01"] = "HEY EKİP, BÜYÜK İŞE GİRİŞMEYE NE DERSİNİZ?",
["loc_vit_cnc_02"] = "GELMİŞ GEÇMİŞ EN BÜYÜK SOYGUNA HAZIR MISINIZ?",
["loc_vit_cnc_03"] = "CAPİTOL HİLL'DE BİR İŞ YAPMAYA NE DERSİNİZ?",
["loc_vit_intro_01"] = "LOCKE HİÇBİR ŞEYİ UNUTMAZ!",
["loc_vit_intro_02"] = "BAIN, HASTA OLDUĞUNU BİLİYORUM AMA BU KESİN EN KÖTÜ ŞAKAYDI!",
["loc_vit_intro_03"] = "O SÖZÜNÜ UNUTMAYACAĞIM SERSEM!",
["loc_vit_intro_04"] = "BENİ NİYE SUÇLUYORSUNUZ? BENİM FİKRİM DEĞİLDİ!",
["loc_vit_intro_05"] = "MURKY'LER HAKKINDAKİ İSTİHBARATIMIZIN YANLIŞ OLMASINDAN BİRAZ ENDİŞELİYİM.",
["loc_vit_intro_06"] = "TAMAM DOSTLARIM, ROLE GİRME VAKTİ.",
["loc_wwh_01_01"] = "KUSURA BAKMAYIN DOSTLAR, BAŞKA TÜRLÜ OLSUN İSTERDİM AMA REDDEDEMEYECEĞİM BİR TEKLİF ALDIM!",
["loc_wwh_01_02"] = "BAŞKA ÇARE YOKTU DOSTLARIM. SADECE İŞ, ANLIYORSUNUZ YA?",
["loc_wwh_01_03"] = "BUNUN İÇİN BENDEN NEFRET EDECEKSİNİZ AMA SADECE ÖLENE KADAR. KİŞİSEL DEĞİL!",
["loc_wwh_02_01"] = "ELVEDA KÜÇÜK GÜLÜMSEYEN DOSTLARIM!",
["loc_wwh_02_02"] = "ELVEDA SEVGİLİ DOSTLAR, BİR DAHA GÖRÜŞECEĞİMİZİ SANMIYORUM!",
["loc_wwh_02_03"] = "İYİ GÜNLER DOSTLAR, BİR DAHA ASLA GÖRÜŞMEMEK ÜZERE!",
["loc_wwh_cbf_01"] = "SEVGİLİ DOSTLAR, BİRKAÇ SİLAHI ELDEN ÇIKARMAK İÇİN YARDIMINIZA İHTİYACIM VAR. ALASKA'DA BİR ANLAŞMA AYARLADIM AMA ALIŞVERİŞİN GÜVENLİ OLMASI İÇİN KORUMA LAZIM, TAMAM MI?",
["loc_wwh_cnc_01"] = "DOSTLAR, BİR SİLAH ANLAŞMASINDA BANA YARDIM ETMEYE NE DERSİNİZ?",
["loc_wwh_cnc_02"] = "ALASKA'DA BİR SİLAH ANLAŞMASI İÇİN YARDIMA İHTİYACIM VAR.",
["loc_wwh_cnc_03"] = "KUZEYDE BİRAZ DONANIM ALIRKEN BANA YARDIM ETMEYE NE DERSİNİZ?",
["loc_wwh_intro_01"] = "BUNU YAPMAK ZORUNDA OLDUĞUM İÇİN ÜZGÜNÜM AMA BEN BURADA TÜYERİM. KİŞİSEL BİR ŞEY DEĞİL!",
["loc_wwh_intro_02"] = "BUNU NASIL SÖYLEYECEĞİMİ BİLMİYORUM AMA PLAN DEĞİŞTİ. ARTIK SİZİ BIRAKMALIYIM!",
["loc_wwh_intro_03"] = "KUSURA BAKMAYIN DOSTLAR, GİTME VAKTİM GELDİ AMA SİZE BİR SÜRPRİZ BIRAKTIM.",
