["max_desc"] = "UYRUĞU: MEKSİKALI$NL;YAŞI: 33$NL;$NL;SANGRES TEHLİKELİ BİR ADAM. MEKSİKA’NIN MONTERREY ŞEHRİNDE BİR UYUŞTURUCU KARTELİ İÇİN YILLARCA TETİKÇİ VE SUİKASTÇI OLARAK ÇALIŞTI. SONRA BİR GÜN SAF DEĞİŞTİRMEYE KARAR VERDİ VE BÜYÜK PARA KAZANMAK İÇİN ABD SINIRINI GEÇTİ. GAGE ONU PAYDAY GANG EKİBİYLE TANIŞTIRDI. ACIMASIZ OLDUĞU KADAR DA BECERİKLİ; ELİNDEKİ REVOLVERLERLE ORTALIĞI GERÇEKTEN ATEŞE VEREBİLİYOR. BİR DE... ŞU JİLET GİBİ KESKİN PALAYA BAK.",
["mayan_gold_bar_obtained"] = "MAYA ALTIN KÜLÇESİ ALINDI",
["mc1_fwb_01_01"] = "YANİ BANA SÖYLEDİĞİNİZ, DOĞRU ANLADIYSAM DEMEK İSTEDİĞİNİZ, ÇAĞRI CİHAZI İŞİNE YATIRIM YAPMAK İSTEMEDİĞİNİZ Mİ?",
["mc1_fwb_01_02"] = "YANİ, DOĞRU ANLADIYSAM, MEKSİKA'DAN SİGARA KAÇIRAN BİR İŞE SERMAYE SAĞLAMAM İÇİN BANA PARA VERMEK İSTEMİYORSUNUZ?",
["mc1_fwb_01_03"] = "TAMAM. YANİ. DOĞRU MU ANLIYORUM, TELEVİZYON PROGRAMI FİKRİMİ FİNANSE ETMEK İSTEMİYORSUNUZ. PİG BROTHER'I?",
["mc1_fwb_01_04"] = "DOĞRU MU ANLADIM? ARKADAŞLARIMA BEDAVA BAR AÇMA İŞ FİKRİM İÇİN CEVABINIZ HAYIR MI?",
["mc1_fwb_01_05"] = "YANİ, DOĞRU MU ANLADIM? AY'A KADAR UZANAN BİR KULE YAPMAK İSTİYORUM, SİZ HAYIR MI DİYORSUNUZ?",
["mc1_fwb_01_06"] = "PEKİ. TAMAM. EMİN MİSİN? MUZLARIN DAHA AZ MUZA BENZEMESİ İÇİN BİR KAMPANYAYA YATIRIM YAPMAK İSTEMİYOR MUSUN?",
["mc1_fwb_01_07"] = "PEKİ, TAMAM. DOĞRU DUYDUYSAM BOOGERS ADLI SALATA BARINI ALMAK İÇİN KREDİYE HAYIR DİYORSUNUZ, ÖYLE Mİ?",
["mc1_fwb_01_08"] = "TAMAM. DOĞRU MU ANLADIM? ARABAMI DENİZALTIYA ÇEVİRMEM İÇİN BANA KREDİ VERMEYECEKSİNİZ?",
["mc1_fwb_01_09"] = "YANİ İŞ PLANIM ALTMIŞ YIL BOYUNCA ISTAKOZ YİYİP ŞAMPANYA İÇERKEN KENDİMİ GÖZLEMLEMEK. KABUL ETMİYORSUNUZ. BİLİM İÇİN BİLE Mİ?!",
["mc1_fwb_02_01"] = "AH. EMİN MİSİNİZ? ÇÜNKÜ PARAYI BİRAZ HARCADIM DA.",
["mc1_fwb_02_02"] = "ŞEY... FİKRİNİZİ DEĞİŞTİREMEM Mİ? YA SİZ... GÖZLERİME BAKIN!",
["mc1_fwb_02_03"] = "SANIRIM BURADA YANLIŞ KAPIYA İŞİYORSUNUZ.",
["mc1_fwb_02_04"] = "ALTIN DEĞERİNDE BİR FIRSATI KAÇIRIYORSUNUZ.",
["mc1_fwb_02_05"] = "BU, EN AZINDAN... BİR MİLYAR DOLAR KAZANMA ŞANSIN OLABİLİRDİ!",
["mc1_fwb_02_06"] = "GERİ GELSEM? BİR DE SALSA GETİRSEM!",
["mc1_fwb_02_07"] = "EVET DEMENİ UMUYORDUM. PARAYLA İÇ ÇAMAŞIRIMI GERİ ALABİLİRDİM.",
["mc1_fwb_02_08"] = "EVET DEMENE BEL BAĞLAMIŞTIM. SONRA YİNE DENERİM.",
["mc1_fwb_02_09"] = "KAHRETSİN. EVET DEMENE BEL BAĞLAMIŞTIM. ",
["mch_brn_02_01b"] = "GELDİĞİNİZE ŞÜKÜRLER OLSUN BE! BU PİÇLER BENİ ÖLDÜRECEKTİ, HEM DE NE İÇİN? SADECE MOTORU ALMAYA GELMİŞTİM... TANRIM...",
["mch_brn_02_02b"] = "YÜCE TANRIM... NEDEN BENİM BAŞIMA GELİYOR? BU BOK ÇUVALLARINI KIZDIRACAK NE YAPTIM BEN? SADECE RUST'IN MOTORUNU ALMAYA GELMİŞTİM...",
["mch_brn_02_03b"] = "AH DOSTUM... KESİN ÖLDÜM SANIYORDUM... BİR GRUP PALYAÇONUN GELİP KIÇIMI KURTARMASINI BEKLEDİĞİMİ SÖYLEYEMEM.",
["mch_brn_03_01b"] = "TEK KELİME ETMEYİN. SADECE GÖTÜMÜ KURTARMAYA GELMEDİĞİNİZİ GAYET İYİ BİLİYORUM. RUST HÂLÂ MOTOSİKLETİNİ GERİ İSTİYOR, DEĞİL Mİ? BUNUN İÇİN BÜTÜN PARÇALAR LAZIM. HER YERE DAĞILMIŞLAR.",
["mch_brn_03_02b"] = "TAMAM TAMAM, BANA ÖYLE BAKMAYIN. SIRF HAYATIMI KURTARMAYA GELDİĞİNİZİ SANACAK KADAR SALAK DEĞİLİM. RUST'I BEN DE TANIYORUM, UNUTTUNUZ MU? BEBEĞİNİ GERÇEKTEN GERİ İSTEDİĞİNİ BİLİYORUM. OLACAKSA GEREKEN PARÇALARI SİZ GETİRMELİSİNİZ.",
["mch_brn_03_03b"] = "EH, SİZİN YERİNİZE SÖYLEYEYİM: BURAYA SADECE BENİ KURTARMAYA GELMEDİNİZ, DEĞİL Mİ? HAYIR, ÖZEL YAPIM MOTOR İÇİN GELDİNİZ. HAKLI MIYIM, HAKLI MIYIM? YARDIM EDERİM. SİZE O KADAR BORCUM VAR AMA GEREKEN PARÇALARI GETİRMELİSİNİZ.",
["mch_brn_04_01b"] = "EYVAH, GELİYORLAR!",
["mch_brn_04_02b"] = "SİKTİR, SİKTİR, SİKTİR! DAHA FAZLASI VAR!",
["mch_brn_04_03b"] = "HAY AMINA KOYAYIM, GELİYORLAR!",
["mch_brn_05_01b"] = "BÖYLE OLMAZ, BÖYLE OLMAZ...",
["mch_brn_05_02b"] = "KENDİMİ NEYİN İÇİNE ATTIM LAN BEN...",
["mch_brn_05_03b"] = "FIRSATIM VARKEN KAÇMALIYDIM...",
["mch_brn_05_04b"] = "MOTORU TAMİR ETMEYİ NİYE TEKLİF ETTİM Kİ...",
["mch_brn_05_05b"] = "HEY! NE OLUYOR LAN!",
["mch_brn_05_06b"] = "HASSİKTİR!",
["mch_brn_05_07b"] = "HASSİKTİR!",
["mch_brn_05_08b"] = "SİKTİR! BUGÜN ÖLMEK İSTEMİYORUM!",
["mch_brn_06_01b"] = "HEY! BENİ BIRAKMAYIN!",
["mch_brn_06_02b"] = "NE OLUYOR LAN! BENDEN KAÇMAYIN!",
["mch_brn_06_03b"] = "ALO? BENSİZ GİTMEYİN!",
["mch_brn_06_04b"] = "NE OLUYOR LAN! BENİ BURADA BIRAKMAYIN!",
["mch_brn_06_05b"] = "HEY! GERİ GELİN!",
["mch_brn_06_06b"] = "NE OLUYOR LAN! GERİ GELİN BURAYA!",
["mch_brn_06_07b"] = "NE BOK YAPIYORSUNUZ? BENİ BIRAKMAYIN!",
["mch_brn_07_01b"] = "HASSİKTİR! YARDIM EDİN!",
["mch_brn_07_02b"] = "YARDIM EDİN!",
["mch_brn_07_03b"] = "SİKTİR! BUGÜN ÖLMEK İSTEMİYORUM!",
["mch_brn_07_04b"] = "AH, SIÇTIK!",
["mch_brn_07_05b"] = "BÖYLE DEĞİL, BÖYLE DEĞİL!",
["mch_brn_07_06b"] = "HEY! YARDIM!",
["mch_brn_07_07b"] = "HEY! BENİ KORUYUN!",
["mch_brn_08_01b"] = "HASSİKTİR, DIŞARISI SAVAŞ ALANI GİBİ! SİZ GİDİP NE YAPIYORSANIZ YAPIN, BEN BURADA KALACAĞIM. PARÇALARI BULUP BURAYA GETİRİN.",
["mch_brn_08_02b"] = "TANRIM, BURADA NE BOK OLUYOR? RUST MOTOSİKLETİNİ GERİ İSTİYOR DİYE BUNCA BOK MU? NEYSE, SİKTİR ET. GİDİP PARÇALARI ALIN VE BURAYA GETİRİN.",
["mch_brn_08_03b"] = "VAY AMINA KOYAYIM... BU BOK YÜZÜNDEN ÖLMEK İSTEMİYORUM... SÖZÜMÜ TUTUP MOTORU TOPLARIM AMA BURADA KALIYORUM. PARÇALARI BULUP BURAYA GETİRİN.",
["mch_brn_09_01b"] = "TAMAM, BİR DÜŞÜNEYİM... NE LAZIM BİZE? HA, ATÖLYE. EVET. ATÖLYEYE GİDİN, ÖZEL ALETLERİ ALET KUTULARINDA BULURSUNUZ.",
["mch_brn_09_02b"] = "ÖZEL ALETLERİM. EVET, KESİNLİKLE ÖZEL ALETLERİM LAZIM. ONLARI ATÖLYEDE BULACAKSINIZ. ALET KUTULARINI ARAYIN.",
["mch_brn_09_03b"] = "TAMAM, MOTORU BİRLEŞTİRMEK İÇİN ÖZEL ALETLERİM LAZIM. ATÖLYEDE, HER ZAMANKİ YERLERİNDE, ALET KUTULARINDAN BİRİNDE OLMALILAR.",
["mch_brn_10_01b"] = "TAMAM, BU GÜZELLİĞE BİR KALP GEREKECEK. MOTOR. ONU DEMEK İSTİYORUM. SANIRIM KULÜP BİNASININ İÇİNDE TUTUYORLAR.",
["mch_brn_10_02b"] = "TAMAM, BU GÜZELLİĞİ YÜRÜTMEK İÇİN BİR MOTOR GEREKECEK. KULÜP BİNASINA BİRKAÇ TANE KOYDUKLARINI GÖRDÜĞÜME NEREDEYSE EMİNİM.",
["mch_brn_10_03b"] = "MOTOR. İHTİYACIMIZ OLAN BU. BENİ EŞEK SUDAN GELENE KADAR DÖVMEYE BAŞLAMADAN ÖNCE KULÜP BİNASINDA BİRKAÇ TANE GÖRDÜM GALİBA.",
["mch_brn_11_01b"] = "SEKSİ AYRINTILARI ATLARSAM RUST BENİ ÖLDÜRÜR. O YÜZDEN KULÜP BİNASINDAN GÜZEL BİR KROM KAFATASI ALMANIZ GEREK. BEN YARIM İŞ YAPMAM, BU BEBEK İÇİN EN İYİSİNİ İSTERİZ.",
["mch_brn_11_02b"] = "GÜZEL MOTORLARIN SIRRI AYRINTILARDA. RUST'IN BEBEĞİ İÇİN EN İYİSİNİ İSTEDİĞİNİ BİLİYORUM. KULÜP BİNASINDA ÖZEL YAPIM KROM KAFATASLARI VAR. GİDİP ALIN.",
["mch_brn_11_03b"] = "ÖZEL MOTOSİKLET TOPLARKEN HER ŞEY AYRINTIDA GİZLİDİR BEBEĞİM. KROM KAPLI SİKİK BİR KAFATASINDAN DAHA HAVALI NE OLABİLİR? HAKSIZ MIYIM? KULÜP BİNASINDA ÖZEL YAPIM BİR TANE GÖRDÜM. ONU BANA GETİRİN.",
["mch_brn_12_01b"] = "AH, AZ DAHA UNUTUYORDUM. İÇERİ GİRMEK İÇİN ŞALOMA KULLANMALISINIZ.",
["mch_brn_12_02b"] = "AH, EVET. DURUN. İÇERİ GİRMEK İÇİN BU ŞALOMA GEREKECEK.",
["mch_brn_12_03b"] = "HEY, ACELE ETME. BU PÜRMÜZÜ AL. İÇERİ GİRMEK İÇİN GEREKECEK.",
["mch_brn_13_01b"] = "TAMAM, RUST'IN NAZLI GÖTÜNE ŞIK BİR SELE LAZIM, DEĞİL Mİ? ARKA BAHÇEDE ESKİ BİR SIĞINAK VAR. İÇERİ GİRİN, İHTİYACIMIZ OLANI BULURSUNUZ.",
["mch_brn_13_02b"] = "TAMAM, DİNLEYİN. ARKA BAHÇEDE BİR SIĞINAK VAR, DEĞİL Mİ? NEDENİNİ SORMAYIN. GİRİN, SÜSLÜ GÖRÜNEN BİR SELE BULACAKSINIZ.",
["mch_brn_13_03b"] = "TAMAM, BU BEBEĞE BİR TAHT LAZIM. NEREDEN BULACAĞIMIZI BİLİYORUM. ŞU ARKA BAHÇEYİ GÖRÜYOR MUSUNUZ? SIĞINAKTA BİR DÜNYA EŞYA SAKLIYORLAR. GİDİP ŞIK BİR SELE GETİRİN.",
["mch_brn_14_01b"] = "TAMAM, İKİ ŞEY LAZIM: YAKIT DEPOSU VE EGZOZ BORULARI. ATÖLYEYE GİRİP TAVAN LİFTİNİ BULUN. ORADA TUTUYORLAR. İNDİRİP İKİSİNİ DE GETİRİN.",
["mch_brn_14_02b"] = "TAMAM, BENZİN DEPOSU VE EGZOZ BORULARI GEREKİYOR. ATÖLYEDE BİR TAVAN LİFTİ VAR, MOTORCULAR ONLARI ORADA TUTUYOR. AŞAĞI İNDİRİP BANA ATIN.",
["mch_brn_14_03b"] = "HMM... AH, TAMAM! EGZOZ BORULARI VE BENZİN DEPOSU LAZIM. ATÖLYEDE BİR TAVAN LİFTİ VAR. YUKARIDA TUTUYORLAR. İKİSİNİ DE GETİRİN, KEYFİM YERİNE GELSİN.",
["mch_brn_15_01b"] = "SİKTİR, BU ZOR OLACAK... EVET, KENDİNİZ YAPAMAZSINIZ. BENİ GARAJA GÖTÜRÜN, BU GÜZELLİĞE ÖZEL PARÇALAR TOPLAMAK İÇİN BİR MOTORU SÖKEYİM.",
["mch_brn_15_02b"] = "TAMAM, DİNLEYİN. BU İŞ BİRAZ ÇETREFİLLİ. BİR MOTOSİKLETİ SÖKÜP ÖZEL BİR ŞEYLER ALMAM LAZIM. YANİ HÜNERLERİMİ GÖSTEREBİLMEM İÇİN BENİ GARAJA GÖTÜRMENİZ GEREKİYOR.",
["mch_brn_15_03b"] = "HIMM... EVET, BAŞKA YOL YOK. GARAJA GİRİP MOTORLARDAN BİRİNİ SÖKMELİYİM. GEREKEN MALZEMEYİ ANCAK ÖYLE ALIRIM. BENİ GÖTÜRÜN, ÇALIŞIRKEN KIÇIMI KORUYUN.",
["mch_brn_16_01b"] = "TEK GİDERSEM VURULURUM, BENİ GARAJA GÖTÜRMENİZ GEREKİYOR. SİZİ BİLMEM AMA BEN ŞU BOKTAN İŞİN BİTMESİNİ İSTİYORUM ARTIK. ",
["mch_brn_16_02b"] = "GARAJA GİRMEM GEREK, SİZİN DE BENİ KORUMANIZ. GİDELİM, HADİ.",
["mch_brn_16_03b"] = "HEY! PALYAÇOLAR! GERÇEKTEN EVE GİTMEK İSTİYORUM, TAMAM MI? O YÜZDEN GEREKEN ŞEYLERİ ALABİLMEM İÇİN LÜTFEN BENİ GARAJA GÖTÜRÜN. ÇALIŞIRKEN DE BENİ KORUSANIZ İYİ OLUR...",
["mch_brn_17_01b"] = "TAMAM, BURADAYIM. BEN ÇALIŞIRKEN ARKAMI KOLLAYIN!",
["mch_brn_17_02b"] = "TAMAM, GELDİM. ŞİMDİ BENİ KORUYUN.",
["mch_brn_17_03b"] = "BENİ KORUYORSUNUZ, DEĞİL Mİ?",
["mch_brn_18_01b"] = "OH, BİTİRDİM. GEREKENİ ALDIM. BENİ KAMYONA GERİ GÖTÜRÜN.",
["mch_brn_18_02b"] = "TAMAM, ALMAYA GELDİĞİMİ ALDIM! BENİ KAMYONA GÖTÜRÜN DE ŞU ŞEYLERİ BİRLEŞTİREYİM.",
["mch_brn_18_03b"] = "TAMAM, TAMAM. GEREKENLERİ ALDIM. BENİ KAMYONA GÖTÜRÜN DE BİTİREYİM.",
["mch_brn_19_01b"] = "SİZİ BİLMEM AMA BEN SUSUZLUKTAN ÖLÜYORUM. BİRİNİZ TATLILIK EDİP OTOMATTAN BANA KOLA GETİRİR Mİ?",
["mch_brn_19_02b"] = "AA! AZ DAHA UNUTUYORDUM! BİR... ÖZEL MALZEME DAHA LAZIM. EVET, AYNEN ÖYLE. TAMİRCİNİN OTOMATTAN BİR KOLA ALMASI GEREKİYOR. ÇABUK ÇABUK, LÜTFEN AMA.",
["mch_brn_19_03b"] = "ÇALIŞMAK İÇİN YAKIT GEREKEN SADECE MOTORLAR DEĞİL, ANLADINIZ MI? HAYIR MI? LANET OLSUN, OTOMATTAN BANA BİR KOLA ALIN İŞTE, OLUR MU?",
["mch_brn_20_01b"] = "GICIKLIK YAPMAK İSTEMEM, GERÇEKTEN, AMA O KOLA KENDİ KENDİNE GELMEYECEK, BİLİYORSUNUZ DEĞİL Mİ?",
["mch_brn_20_02b"] = "MİLLET, LÜTFEN. PROFESYONEL ADAMIN ÇALIŞIRKEN ATIŞTIRMALIĞI LAZIM. O KOLAYI GETİRİN DE TAMİRCİNİN YÜZÜ GÜLSÜN.",
["mch_brn_20_03b"] = "HADİ, KOLA NEREDE? SUSADIM!",
["mch_brn_21_01b"] = "AH, BU MUHTEŞEM OLACAK AMINA KOYAYIM! SIRADAKİ PARÇAYI GETİRİN!",
["mch_brn_21_02b"] = "TAMAM, BU İŞ GÖRÜR! SIRADA NE VAR?",
["mch_brn_21_03b"] = "BİTTİ! SIRADAKİ PARÇAYI GETİRİN!",
["mch_brn_22_01b"] = "HEY! NE OLUYOR LAN! BU SİKİK POLİSLERİ KIÇIMDAN UZAK TUTUN!",
["mch_brn_22_02b"] = "HEY! NE OLUYOR LAN! BU POLİSLER BURNUMUN DİBİNDEYKEN ÇALIŞAMAM!",
["mch_brn_22_03b"] = "VAY, HEY! BÖYLE İŞİMİ NASIL YAPAYIM? HALLEDİN ONLARI!",
["mch_brn_22_04b"] = "BÖYLE NASIL ÇALIŞAYIM BEN?!",
["mch_brn_22_05b"] = "NE OLUYOR LAN! BENDEN UZAK TUTUN ŞUNLARI!",
["mch_brn_22_06b"] = "LANET OLSUN MİLLET! BENİ KORUYUN!",
["mch_brn_22_07b"] = "BENİM LANET KORUMAM NEREDE?!",
["mch_brn_22_08b"] = "BANA BU KADAR YAKLAŞMALARINA İZİN VERMEYİN AMINA KOYAYIM!",
["mch_brn_23_01b"] = "HAY SİKEYİM... ÇOK UCUZ ATLATTIK.",
["mch_brn_23_02b"] = "KUTSAL MERYEM ANA, LÜTFEN BİR GÜN DAHA YAŞAYAYIM... BEN İYİ ÇOCUĞUM, DEĞİL Mİ?",
["mch_brn_23_03b"] = "SEVGİLİ BEBEK İSA, BENİ KORU...",
["mch_brn_23_04b"] = "HASSİKTİR... ŞU BOK BİTSİN ARTIK İSTİYORUM...",
["mch_brn_23_05b"] = "TANRIM... BEN BU BOKA NASIL BULAŞTIM AMINA KOYAYIM...",
["mch_brn_23_06b"] = "ÇOK YAKINDI AMINA KOYAYIM... ÇOK YAKINDI...",
["mch_brn_23_07b"] = "ONUN YERİNE BOKTAN BİR OFİS İŞİ BULMALIYDIM...",
["mch_brn_23_08b"] = "HERKES BANA ATEŞ EDİYOR LAN... SİKTİĞİMİN İŞİ...",
["mch_brn_24_01b"] = "VEEE BİTTİ! YEPYENİ GİBİ... ELVEDA SEVGİLİM... ÖZLEYECEĞİM SENİ... SENİ SEVİYORUM.",
["mch_brn_24_02b"] = "İŞTE BU BAYANLAR BAYLAR. İŞ. TAMAM. ŞİMDİ BURADAN SİKTİR OLUP GİTMEM GEREKİYOR!",
["mch_brn_24_03b"] = "BENİ BİR GÜZEL SİKSİNLER: BİTİRDİK! BU MOTORU ALIN DA DEFOLUN BURADAN. BİR SANİYE DAHA KALMAM!",
["mch_brn_25_01b"] = "OO, BİR ŞEYLER Mİ ÇALIYORUZ? SEVDİM. ŞU SİKTİĞİMİN MOTORCULARININ HAYATINI ZEHİR EDECEK HER ŞEYE VARIM. BAGAJA KOYUN, GİDERKEN YANIMDA GÖTÜREYİM. AYRINTILARI SONRA HALLEDERİZ!",
["mch_brn_25_02b"] = "ELİNİZDEKİ NE? GERÇİ HİÇ UMURUMDA DEĞİL. KAMYONA ATIVERİN, GİDERKEN YANIMDA GÖTÜRÜRÜM.",
["mch_brn_25_03b"] = "KAMYONA ATIN, SONRA İLGİLENİRİZ!",
["mch_pal_01_01"] = "PARAMI NASIL MI KAZANIYORUM? ŞÖYLE DİYELİM... YANİ, ÇOĞUNU... KENDİM BASIYORUM DİYEBİLİRSİNİZ.",
["mch_pal_01_02"] = "PARAMI NASIL MI KAZANIYORUM? ÇOK... BASTIĞIMI SÖYLEYEBİLİRSİN.",
["mch_pal_01_03"] = "PARAMI NASIL MI KAZANIYORUM? YAYINCILIK. EVET, YAYINCILIK.",
["mch_pal_01_04"] = "PARAMI NASIL KAZANDIĞIMI MI ÖĞRENMEK İSTİYORSUNUZ? ÇOK ÇALIŞARAK. BÜTÜN GECE BOYUNCA.",
["mch_pal_01_05"] = "PARAYI NASIL MI KAZANIYORUM? TUTUYORUM İŞTE. EVET.",
["mch_pal_01_06"] = "AH, İŞİM EPEY SIKICI. TEKDÜZE. MAKİNE GİBİ. AMA İYİ KAZANDIRIYOR.",
["mch_pal_01_07"] = "PARAM... ŞEY, BİR TÜR GÜVEN FONUNDAN GELİYOR. SİZİ DE ORTAK EDERDİM... AMA SİZE GÜVENMİYORUM.",
["mch_pal_01_08"] = "SERVETİNİ KENDİ YAPMIŞ BİR MİLYONERİM. PARA BİTİNCE NE OLUR, BİR MİLYON DAHA YAPARIM.",
["mch_pal_02_01"] = "BİR ADAM GELDİ İŞTE, ANLIYOR MUSUN, HEPSİNİ ALMAK İSTEDİ AMA DEDİM Kİ, BU SADECE PARA, BEN BÖYLE BİRİ DEĞİLİM... ANLADIN MI?",
["mch_pal_02_02"] = "YAPTIĞIM İŞİ SEVİYORUM, ANLIYOR MUSUN? YARATICI OLDUĞUMDA DA KENDİMİ DÜNYANIN TEPESİNDE HİSSEDİYORUM. ÇÜNKÜ, BİLİRSİN, BENİM YAPTIĞIMI KAÇ KİŞİ YAPABİLİR Kİ?",
["mch_pal_02_03"] = "KÜÇÜCÜK BİR ÇOCUKKEN BİLE HEP BÜYÜK OYNAMAK İSTEMİŞİMDİR, ANLIYOR MUSUN?",
["mch_pal_02_04"] = "EVET, EVET... BANA SORARSAN, ONU ÇOK İSTİYORDUM, O YÜZDEN DE FAZLASIYLA HAK EDİYORDUM. ANLIYOR MUSUN?",
["mch_pal_02_05"] = "BÜTÜN PARÇALARI YERİNE KOYMAK ZOR OLMADI. ",
["mch_pal_02_06"] = "ASLINDA SADECE İŞLERİMİ DÜZENE SOKMA MESELESİYDİ, ANLIYOR MUSUN?",
["mch_pal_02_07"] = "PARA KAZANMAK O KADAR ZOR DEĞİL.",
["mch_pal_02_08"] = "DİNLE, SEVDİĞİN ŞEYİ YAPIP PARA ALMAK VAR YA... RÜYA GİBİ DOSTUM.",
["mch_pal_02a_01"] = "BEN PARAMI ÇEKİNCE DİĞER BÜTÜN GÖTLER DE AYNISINI YAPTI. AMA AKILLIYDIM. İLK ÇIKAN BENDİM, ANLIYOR MUSUN? BİR ANDA BİR MİLYON DOLAR KAZANDIM.",
["mch_pal_02a_02"] = "FIRSAT YARATABİLİRSİN AMA HAYATTA BİR KEZ GELEN FIRSATA NE ZAMAN ATILACAĞINI DA BİLMEN GEREKİR. BEN DE HİÇ ÇEKİNMEDEN ATILDIM!",
["mch_pal_02a_03"] = "PARA KAZANMAK ÇOK ÇALIŞMAKLA İLGİLİ DEĞİL. NE ZAMAN BANKACINI ARAYIP 'SAT' DİYECEĞİNİ BİLMEKLE İLGİLİ.",
["mch_pal_02a_04"] = "BİR ARA SAAT BAŞINA BENEVOLENT BANK'TEN DAHA ÇOK KAZANIYORDUM.",
["mch_pal_02a_05"] = "DOSTUM, YEPYENİ YÜZ DOLARLIK BANKNOTUN KOKUSUNA BAYILIRIM. ANLIYOR MUSUN?",
["mch_pal_02a_06"] = "BİR SÜRE PARA KAZANMAK SORUN DEĞİLDİ, HARCAMAK SORUNDU!",
["mch_pal_02a_07"] = "ADAMIN BİR GÜNDE BİR MİLYAR DOLAR HARCAMASI GEREKEN FİLMİ GÖRDÜN MÜ? ÖYLE BİR ŞEY. İŞTE O PİÇ BENDİM.",
["mch_pal_02a_08"] = "PARAMI ALIP ÇIKTIM. BİR MİLYON KAZANDIM AMINA KOYAYIM. İKİ MİLYON! DAHA DA FAZLA!",
["mch_pal_03_01"] = "BEN DE ONA DEDİM Kİ, HANİ, ‘MITCHELL... MİCHELLE DEĞİL. KANADALI DEĞİLİM AMINA KOYAYIM!’ ANLADIN MI?",
["mch_pal_03_02"] = "BU HATUNLAR, BİLİRSİNİZ, KAÇA PATLIYOR BİLİYOR MUSUNUZ? HER GÜN? AMA HEY, DEĞER.",
["mch_pal_03_03"] = "ETRAFIMDAKİ ONCA GÜZEL GÖT. KAÇ PARA EDİYOR BİLİYOR MUSUN? AMA DEĞERLER. YANİ DANS EDEBİLİYORLAR. DANS DERKEN DE...",
["mch_pal_03_04"] = "DÜNYAYI YELKENLİYLE DOLAŞACAĞIZ. ŞURADAKİ TEKNEYİ GÖRÜYOR MUSUN? BİR MİLYON BAYILDIM ONA, ŞEY, BİLMİYORUM... BELKİ BU YIL DENİZE İNDİRİRİZ. BAKACAĞIZ.",
["mch_pal_03_05"] = "TABİİ BU MÜLKLERDEN SADECE BİRİ. YANİ... BİR KERESİNDE BURAYA GELİRKEN ALDIĞIM KÜÇÜK BİR ŞEY. İKİ ÜÇ YIL ÖNCE FALAN.",
["mch_pal_03_06"] = "PARAYI GAYRİMENKULE YATIRABİLİRDİM. BEN DE GAYET MEMELİYE YATIRIYORUM!",
["mch_pal_03_07"] = "SONRA FARK ETTİM, RULO YAPIP BİR OROSPUNUN KIÇINDAN TOZ ÇEKMİYORSAN PARA NEYE YARAR?",
["mch_pal_03_08"] = "ADIM MITCHELL. MITCHELL! MİTCH... ELL. ŞİMDİ BİR DE SİZ SÖYLEYİN.",
["mch_pal_04_01"] = "BİLİRSİNİZ, BEN VE KİNG, HA? ŞEHİRDE TURLAYIP SAĞDAN SOLDAN KIZ TOPLARDIK. MASRAFLARIN ÇOĞUNU BEN ÖDERDİM TABİİ.",
["mch_pal_04_02"] = "KRAL EĞİLİP ‘İKİSİ SANA, İKİSİ BANA’ DİYOR. BİLİRSİN İŞTE. SÜPER MODELLERDEN BAHSEDİYOR. TATLI MI TATLI AŞK!",
["mch_pal_04_03"] = "BİR SÜPER MODEL KUCAĞIMDA, İKİNCİSİ BANA HARİKA BİR CİN TONİK HAZIRLIYOR. KRAL DÖNÜP GÖZ KIRPIYOR.",
["mch_pal_04_04"] = "KENDİME YENİ BİR FALCOGİNİ ALMIŞTIM. TİME OUT'TAN ÇIKARKEN ÇİZDİM. YOL KENARINA BIRAKIP GİTTİM. ÇİZİK ARABAYLA KİM UĞRAŞACAK!",
["mch_pal_04_05"] = "ORİJİNAL BİR GUSTAV ALDIM. THE KING ONU RULO YAPIP FAHİŞENİN KIÇINDAN TOZ ÇEKMEK İÇİN KULLANMIŞ. BİLİRSİN.",
["mch_pal_04_06"] = "KRAL'I TANIYORSUN, DEĞİL Mİ? SORMAN GEREKİYORSA TANIMIYORSUNDUR ZATEN.",
["mch_pal_04_07"] = "KRAL EN TEPEDEYDİ, BÜYÜK BABAYDI, O... BİLDİĞİN KRALDI DOSTUM!",
["mch_pal_04_08"] = "KİNG, BİLİRSİNİZ KİNG'İ. O ŞİŞKO PİÇ KOKAİN ÇEKMEYİ ÇOK SEVERDİ.",
["mch_pal_04a_01"] = "BİZİM TARZIMIZ BUYDU.",
["mch_pal_04a_02"] = "YANİ, HEY. BİZ KRAL GİBİYDİK, ANLIYOR MUSUN?",
["mch_pal_04a_03"] = "EVET. O KRAL'DI AMA BEN DE BİLDİĞİN CEASAR'DIM, ANLIYOR MUSUN?",
["mch_pal_04a_04"] = "SİKTİĞİMİN YETMİŞLERİ GİBİYDİ DOSTUM. PARA, KOKAİN, FAHİŞELER... HEPSİ BİZDEYDİ.",
["mch_pal_04a_05"] = "YILLARI GERİ SARDIK. STRİP'TE 69 YILI GİBİYDİ. ARKADAKİ ONCA KADINDAN CADİLLAC YERE YAPIŞMIŞTI.",
["mch_pal_04a_06"] = "ÇÜNKÜ UYANDIĞIMIZ ANDAN İTİBAREN ÖYLEYDİ. HER GÜN, BÜTÜN GÜN. FAHİŞELER VE KOKAİN.",
["mch_pal_04a_07"] = "İŞTE BUNLAR SADECE PARANIN GETİRECEĞİ ŞEYLER. BİR YAŞAM TARZI, ANLIYOR MUSUN?",
["mch_pal_04a_08"] = "OYUNU OYNAMAK GEREK AMA OYUNA HİLE DE KATMAK GEREK DOSTUM!",
["mch_pal_04b_01"] = "DESTAN GİBİ LAN, DOSTUM.",
["mch_pal_04b_02"] = "EFSANE GÜNLERDİ.",
["mch_pal_04b_03"] = "RUHUMU COŞTUR, BİLİRSİN İŞTE.",
["mch_pal_04b_04"] = "GÜZEL GÜNLERDİ, BİLİRSİN.",
["mch_pal_04b_05"] = "DEVİR KUDURUYOR, BİLİRSİNİZ.",
["mch_pal_04b_06"] = "YAŞAMAK İÇİN NE GÜZEL ZAMAN...",
["mch_pal_04b_07"] = "ABARTTINIZ BE.",
