["menu_bodhi_desc_codex"] = "BODHI, SUÇ DÜNYASININ EN BÜYÜK EFSANELERİNDEN BİRİ OLARAK BİLİNİR AMA MASKENİN ARDINDAKİ ADAMI PEK AZ KİŞİ TANIR. EX-PRESİDENTS ÇETESİNİN KURUCUSU BODHI, OLAĞANÜSTÜ ATLETİK YETENEKLERİ VE CÜRETKÂR SOYGUNLARIYLA SUÇ DÜNYASINDA ÜN SALMIŞTIR. MUMBAİ VE AVUSTURYA’DAKİ SON GÖVDE GÖSTERİLERİ BAIN’İN DİKKATİNİ ÇEKMİŞ VE ONA PAYDAY GANG EKİBİNE KATILMA DAVETİ KAZANDIRMIŞTIR.",
