["menu_challenge_introduction_desc"] = "DİNLEYİN SOYGUNCULAR,$NL;$NL;BAĞLANTILARIMIZDAN BİRİ ARA SIRA ÖZEL BİR İSTEKLE BANA GELİR.$NL;HANİ ŞU KÜÇÜK \"ORALARDAYSAN BELKİ ŞUNU DA YAPABİLİRSİN...\" İSTEKLERİ. VLAD’IN ÇAMAŞIRLARINI ALMAKTAN VEYA THE ELEPHANT’A SÜT VE EKMEK GÖTÜRMEKTEN BAHSETMİYORUM. HIRSIZLIK YAPMAK, SOYMAK, ATEŞ ETMEK VE ZENGİN OLMAK İÇİN EK FIRSATLARDAN BAHSEDİYORUM.$NL;$NL;BUNU YAPMAKTA TEREDDÜT ETTİM. DİKKAT DAĞILMASIN; ELDEKİ İŞE ODAKLANMAK GEREK, DEĞİL Mİ? AMA BUNCA SAATTEN SONRA BUNU DA YAPABİLECEĞİNİZİ DÜŞÜNÜYORUM. BU YÜZDEN CRIME.NET’E YENİ BİR ÖZELLİK EKLİYORUM: GÜNLÜK, HAFTALIK VE AYLIK İŞLER. BİRAZ FAZLADAN İŞ YAP, BÜYÜK ÖDÜL KAZAN. BİR BAKIN, HANGİLERİ ETKİN GÖRÜN. BAĞLANTILARIMIZIN FAZLADAN ÇABA GÖSTERENLERE CÖMERT DAVRANDIĞINI BİLİRSİNİZ.",
