["menu_challenge_stat_boost"] = "RASTGELE ÖZELLİK TAKVİYESİ",
["menu_challenge_still_retrieving"] = "YAN İŞLER CRIME.NET’TEN İNDİRİLİYOR",
["menu_challenge_summary_desc"] = "YAN İŞLER, BELİRLİ MEYDAN OKUMALARI BAŞARIYLA TAMAMLAYARAK ÖDÜL KAZANMANIN BİR YOLUDUR. ÜÇ TÜR YAN İŞ VARDIR: GÜNLÜK, HAFTALIK VE AYLIK. DÜZENLİ ARALIKLARLA GÜNCELLENİRLER; BÖYLECE YENİ GÜNLÜK, HAFTALIK VE AYLIK İŞLERE ERİŞEBİLİR, DAHA ÖNCE BİTİREMEDİKLERİNİ TAMAMLAYABİLİRSİN. BİR YAN İŞ TAMAMLANINCA BUNU BİLDİREN BİR TEZAHÜRAT SESİ DUYULUR. GÜNCELLENENE KADAR HER BİRİNİ YALNIZCA BİR KEZ TAMAMLAYABİLİRSİN$NL;$NL;SENDEN İSTENENİ YAPTIĞINDA YAN İŞ SARIYA DÖNER. BU, ÖDÜLÜNÜ ALABİLECEĞİN ANLAMINA GELİR. SARIYLA İŞARETLİ GÜNLÜK, HAFTALIK VEYA AYLIK İŞE GİT VE ALMAK İÇİN ÖDÜL KUTUSUNDA GÖRÜNEN HER EŞYAYA TIKLA.$NL;$NL;GÜNLÜK İŞLER, SEÇTİĞİN SİLAH İÇİN RASTGELE BİR MODİFİKASYON VE PARA VERİR. HER 24 SAATTE YENİLENİR.$NL;HAFTALIK İŞLER, BELİRLİ BİR MASKE VE PARA VERİR. HER 7 GÜNDE YENİLENİR.$NL;AYLIK İŞLER, ÖZELLİK TAKVİYESİ VEYA EKİP TAKVİYESİ SİLAH MODİFİKASYONU VERİR. HER AY YENİLENİR.",
["menu_challenge_summary_title"] = "TEMEL PROSEDÜR",
["menu_challenge_the_first_line"] = "İLK HAT",
["menu_challenge_the_first_line_desc"] = "THE ELEPHANT, NADİR SPOR HATIRALARI TOPLUYOR. FİRESTARTER’IN 3. GÜNÜNDEKİ KİRALIK KASALARDAN BİRİNDE OVERKILL HOKEY TAKIMININ NADİR BİR POSTERİ VAR. ONU AL!",
["menu_challenge_the_first_line_objective"] = "FİRESTARTER İŞİNİN 3. GÜNÜNDE OVERKILL HOKEY TAKIMININ NADİR HOKEY POSTERİNİ BUL.",
