["menu_challenge_vlad_4_jobs"] = "VLAD KÜPLERE BİNDİ!",
["menu_challenge_vlad_4_jobs_desc"] = "VLAD ÇARESİZCE DİKKATİNİ ÇEKMEYE ÇALIŞIYOR. HERHANGİ BİR ZORLUKTA VLAD’IN 4 İŞİNİ TAMAMLA.",
["menu_challenge_vlad_4_jobs_objective"] = "TAMAMLANAN İŞLER: $progress;/$max_progress;",
["menu_challenge_voff_1_desc"] = "ASLA AŞILMAMASI GEREKEN BİR ÇİZGİ VARDIR. DOMUZLARA ZARAR VERMEKTEN BAHSETMİYORUZ; KÖPEKLERE ZARAR VERMEKTEN BAHSEDİYORUZ. ONLAR İNSANIN EN İYİ DOSTUDUR; ÜSTELİK İNSANLARIN AKSİNE SADIK VE İTAATKÂRDIRLAR. BU YÜZDEN SEVİMLİ BİR DACHSHUND’A VEYA SCHNAUZER’A YAN GÖZLE BAKMAN BİLE SENİ AVLAMAMIZ İÇİN YETERLİ SEBEPTİR.",
["menu_challenge_voff_1_objective"] = "BANK HEIST İŞİNİ OVERKILL VEYA ÜZERİ ZORLUKTA, OTOPARKTAKİ 2 SERSERİYİ BULUP KAÇMALARINA VEYA ÖLMELERİNE İZİN VERMEDEN MİNİBÜSÜN YANINA GETİRDİKTEN SONRA TAMAMLA.",
["menu_challenge_voff_2"] = "KAFASI YÜKSEK GÜNLER",
["menu_challenge_voff_2_desc"] = "UYUŞTURUCUYU ELE GEÇİRMEK EZİYET OLABİLİR AMA İŞİ BİTİRİNCE BUNA DEĞER. TABİİ BU SIRADA ÖLMEZSEN. THE BUTCHER MEVCUT TÜM METAMFETAMİNİ İSTİYOR. O YÜZDEN DÖKME VE HAYATTA KAL!",
["menu_challenge_voff_2_objective"] = "THE BOMB: DOCKYARD SOYGUNUNDA 2 ÇANTA METAMFETAMİN PİŞİR VE ELE GEÇİR.",
["menu_challenge_voff_3"] = "KARANLIKTA YAĞMA",
["menu_challenge_voff_3_desc"] = "JIMMY KOKAİNLE KAFAYI BULMUŞ, SONU GELMEYECEKMİŞ GİBİ GÖRÜNEN BİR UYUŞTURUCU ÇILGINLIĞI İÇİNDE \"ŞANLI HAVALI ŞEYLER\" DİYE BAĞIRIP DURUYOR. MURKY STATION GANİMET DOLU. O YÜZDEN ALIN, ÇIKIN VE KİMSEYİ ÖLDÜRMEYİN.",
["menu_challenge_voff_3_objective"] = "MURKY STATION İŞİNİ OVERKILL VEYA ÜZERİ ZORLUKTA KİMSEYİ ÖLDÜRMEDEN, TÜM GANİMETİ BULUP ELE GEÇİREREK TAMAMLA.",
["menu_challenge_voff_4_desc"] = "UÇAĞA BİNMEK, DÜŞMANLARI ÖLDÜRMEK, HAYATTA KALMAK VE DÜNYANIN DÖRT BİR YANINDAKİ KRALLARA VERİLMİŞ DOKUZ YÜZÜĞÜ BULMAK ÖYLE KOLAY DEĞİLDİR. AMA DENEMEYE DEĞER.",
["menu_challenge_voff_4_objective"] = "BIRTH OF SKY SOYGUNUNDA 9 YÜZÜĞÜN TAMAMINI BUL.",
["menu_challenge_voff_5"] = "ŞEFİ ÖP",
["menu_challenge_voff_5_desc"] = "PİŞİRMEK ACAYİP RAHATLATICI OLABİLİR. OCAĞIN BAŞINDA TAKILIP ÇOK LEZZETLİ OLACAK GÜZEL ŞEYLER KARIŞTIRMAK. BİRAZ HİDROKLORİK ASİT EKLE VE O MUHTEŞEM YAHNİNİN KOKUSUNU ÇEK.",
["menu_challenge_voff_5_objective"] = "COOK OFF İŞİNDE OVERKILL VEYA ÜZERİ ZORLUKTA 25 ÇANTA METAMFETAMİN PİŞİR.",
["menu_challenge_weekly_reward"] = "PARA VE KÖTÜ ŞÖHRETLİ BİR EŞYA.",
["menu_challenge_winters_mutated"] = "KLONLARIN KAPTANI",
["menu_challenge_winters_mutated_desc"] = "AŞMAMIZ GEREKEN TEK VE ÖZEL BİR BAŞ DÜŞMANIMIZ PEK SIK OLMAZ. OLDUĞUNDAYSA BUNU NEREDEYSE BİR LÜTUF SAYABİLİRİZ.",
