["menu_challenge_xmas_all"] = "NOEL FELAKETİ",
["menu_challenge_xmas_all_desc"] = "BÜTÜN POLİSLERİN BOZUK YUMURTA LİKÖRÜ İÇİP BİR DEĞİŞİKLİK OLSUN DİYE YOLUMUZDAN ÇEKİLDİĞİ BİR NOEL HAYAL EDİYORUM.",
["menu_challenge_xmas_all_obj"] = "WHITE XMAS, SANTA'S WORKSHOP VE STEALING XMAS SOYGUNLARINI TAMAMLA. BU MEYDAN OKUMAYI TAMAMLAMAK İÇİN SOYGUNLARI BAŞTAN SONA OYNAMIŞ OLMALISIN.",
["menu_challenge_xmas_walking_nightmare"] = "YÜRÜYEN KÂBUS",
["menu_challenge_xmas_walking_nightmare_desc"] = "\"DÜN GECE RÜYAMDA NOEL BABA KIYAFETLİ BİR İSKELET GÖRDÜM. AMA KIYAFETİ ÇIKARDIĞINDA İSKELET DEĞİL, BİR KİNG CLOAKER ÇIKTI. NASIL OLUYOR HİÇ FİKRİM YOK. RÜYALAR ÇOK ACAYİP ŞEYLER.\"",
["menu_challenge_xmas_walking_nightmare_obj"] = "WAKİNG NİGHTMARE DEĞİŞTİRİCİSİ AÇIKKEN WHITE XMAS, SANTA'S WORKSHOP VEYA STEALING XMAS İŞLERİNDEN HERHANGİ BİRİNİ TAMAMLA. BU MEYDAN OKUMAYI TAMAMLAMAK İÇİN SOYGUNU BAŞTAN SONA OYNAMIŞ OLMALISIN.",
