["menu_contact_filter"] = "KULLANILABİLİR BAĞLANTILAR",
["menu_contact_info_chill_combat"] = "GÜVENLİ EV",
["menu_contact_info_title"] = "CRIME.NET/BAĞLANTI_VERİTABANI",
["menu_contacts"] = "BAĞLANTILAR",
["menu_content_akm4_pack_date"] = "26 ŞUB 2015",
["menu_content_akm4_pack_desc"] = "EN SEVİLEN KLASİKLER OLAN AMERİKAN CAR VE RUS AK SİLAHLARINA YÖNELİK MODİFİKASYONLARLA DOLU BÜYÜK BİR SEVKİYAT, DOĞU YAKASI’NA DOĞRU YOLDA. THE BUTCHER’S AK/CAR MOD PACK, PAYDAY 2’NİN 19. DLC PAKETİDİR. THE BUTCHER, EN POPÜLER İKİ SİLAH AİLESİNE ÖZEL MODİFİKASYONLAR SUNARAK PAZARDAN PAY KAPMAK İSTİYOR; BUNUN İYİ BİR NEDENİ VAR. BU BASİT VE SAĞLAM SİLAHLAR, İSTEDİĞİN HER ROLE UYGUN HÂLE GETİRİLEBİLİYOR. PAKETE 22 YENİ SİLAH MODİFİKASYONU VE TARİH ÖNCESİ ÇAĞLARDAN 4 YENİ MASKE EKLENİYOR. SİLAH MODİFİKASYONLARININ KİLİDİNİ AÇMANA YARDIMCI OLACAK 8 YENİ BAŞARIM DA VAR.",
["menu_content_arena_desc"] = "THE ALESSO HEIST DLC, PAYDAY 2’NİN 23. DLC PAKETİDİR VE DJ ALESSO İLE ORTAK ÇALIŞMADIR. SESSİZCE VEYA ÇATIŞARAK GENSEC ARENASINDA İLERLE; GENSEC’İN PARA DOLU SON TEKNOLOJİ SERGİ KASALARINI AÇMAYA ÇALIŞIRKEN GÖSTERİ DEVAM ETSİN. THE ALESSO HEIST DLC, ALESSO İLE BİRLİKTE TASARLANDI. STARBREEZE SUNS HOKEY TAKIMININ EV ARENASINDA YENİ PAYDAY ŞARKISINI, ADRENALİN DOLU ÇATIŞMALARI VE GERGİN GİZLİLİK ANLARINI SUNAR. AYRICA GÜÇLÜ VE DÜŞÜK GERİ TEPMELİ MATEVER .357 REVOLVERİNİ, ALESSO’NUN GÖSTERİLERİNDEN ESİNLENEN 4 MASKE, 4 DESEN, 4 MALZEME VE 5 BAŞARIM İÇERİR.",
["menu_content_armored_transport_date"] = "14 KAS 2013",
["menu_content_armored_transport_desc"] = "THE ARMORED TRANSPORT DLC, PAYDAY 2’NİN İKİNCİ DLC PAKETİDİR. OYUNCULARA HER SOYGUNCUNUN HAYALİNİ YAŞATIR: WASHINGTON D.C.’NİN TAM ORTASINDA DEĞERLİ EŞYALARLA DOLU ZIRHLI NAKLİYE ARAÇLARINI SOYMAK.$NL;$NL;SOYGUNLARDA EN FAZLA DÖRT ARKADAŞ İŞBİRLİĞİ YAPAR. EKİP İLERLEDİKÇE DAHA DA KAZANÇLI BİR İŞİN, KLASİK TREN SOYGUNUNUN KİLİDİNİ AÇMA ŞANSI YAKALAR. OYUNCULAR SİLAH VE EKİPMANLARINI OLUŞTURMAYA VE ÖZELLEŞTİRMEYE DEVAM EDEBİLSİN DİYE YENİ SİLAHLAR, SİLAH MODİFİKASYONLARI, MASKELER, DESENLER VE MALZEMELER EKLENDİ.",
["menu_content_bbq_desc"] = "ORTALIK KIZIŞIYOR! THE BBQ WEAPON PACK, PAYDAY 2’NİN 18. DLC PAKETİDİR. FLAMETHROWER MK.1 İLE OYUN TARZINI HARLA VE BİR EJDERHA GİBİ ALEV PÜSKÜRT. ALEV PÜSKÜRTMEK İLGİNİ ÇEKMİYORSA DÜŞMAN GRUPLARINI HIZLA TEMİZLEYEN YARI OTOMATİK PIGLET BOMBA ATARINA NE DERSİN? ÜSTELİK UZAĞI YAKMAK İSTERSEN ONA STANDART PARÇA TESİRLİ MÜHİMMAT VEYA YENİ YANGIN MÜHİMMATI YÜKLEYEBİLİRSİN. YA DA ESKİ USUL FIRLATILABİLİR MOLOTOF KOKTEYLLERİ? BARBEKÜ SEVENLER İÇİN FORK, TENDERİZER, SPATULA VE POKER ADLI 4 YENİ YAKIN DÖVÜŞ SİLAHI EKLİYORUZ. PAKET AYRICA STEAKOUT 12G POMPALI TÜFEĞİNİ, DRAGON’S BREATH POMPALI MÜHİMMATI MODİFİKASYONU, DÖRT MASKE VE BEŞ BAŞARIM İÇERİYOR. İYİCE ÇITIR OLSUN DİYE.",
["menu_content_berry_date"] = "03 ARA 2015",
["menu_content_berry_desc"] = "THE POİNT BREAK HEİSTS, PAYDAY 2’NİN 29. DLC PAKETİDİR VE ALCON ENTERTAİNMENT, WARNER BROS. PİCTURES VE LİONSGATE ORTAKLIĞIYLA HAZIRLANDI. POİNT BREAK, PAYDAY OYUNLARINI YAPARKEN BÜYÜK BİR İLHAM KAYNAĞI OLDUĞUNDAN BU İKİ SOYGUNU HAZIRLAMAK OVERKILL İÇİN BİR HAYALİN GERÇEKLEŞMESİYDİ. \"BENEATH THE MOUNTAIN\" SOYGUNUNDA PAYDAY GANG, MURKYWATER ADLI PARALI ASKER ORDUSUNUN KENDİ KOMUTA MERKEZİNE SIZARAK ONLARLA KARŞI KARŞIYA GELİYOR. İŞLER UÇ NOKTALARA GİTMESE BUNA POİNT BREAK SOYGUNU DENMEZDİ. \"BIRTH OF SKY\" SOYGUNUNDA İSE ÇETE, YERDEN 20.000 FİT YÜKSEKTEKİ BİR KARGO UÇAĞINI SOYACAK. PARAYI ALMAK BİR MESELE; UÇAKTAN ÇIKMAKSA BAMBAŞKA BİR MESELE.",
["menu_content_big_bank_date"] = "17 HAZ 2014",
["menu_content_big_bank_desc"] = "THE BIG BANK HEİST DLC, PAYDAY 2’NİN SEKİZİNCİ DLC PAKETİDİR VE DENTİST ADLI YENİ BAĞLANTININ İLK SOYGUNUNU EKLER. PARA BU ŞEHRİN CAN DAMARIYSA BENEVOLENT DA ATAN KALBİDİR.$NL;BU, İSTER SESSİZ BİR KURNAZLIKLA İSTER AMANSIZ GÜÇLE GERÇEKLEŞTİRİLSİN, BANKA SOYGUNLARININ ZİRVESİDİR. KUSURSUZ SOYGUNU PLANLAYIP BİG BANK’İ AÇARAK TARİH YAZABİLİR MİSİN? BENEVOLENT HİÇ SOYULMADI. PEK ÇOK KİŞİ DENEDİ. 40’TA NESTOR ÇETESİ, 77’DE BELTWAY BUNCH. HEPSİ BAŞARISIZ OLDU. BUNU SEN DEĞİŞTİRECEKSİN. BİG BANK İŞİNİN YANINDA FALCON TÜFEĞİNİ VE MODİFİKASYONLARINI, DÖRT YEPYENİ MASKE, MALZEME VE DESENİ DE ALACAKSIN. SANA GERÇEK BİR MEYDAN OKUMA SUNMAK İÇİN SOYGUNA ÖZEL 10 BAŞARIM EKLENDİ.",
["menu_content_birthday_date"] = "18 EKİ 2013 - 23 EKİ 2013",
["menu_content_birthday_desc"] = "PAYDAY İKİ YAŞINDA! MUTLU YILLAR! PEKİ BU NE ANLAMA GELİYORDU? OVERKILL OLARAK 18 EKİM’DEN BAŞLAYARAK İKİ YILLIK SOYGUNLARI SİZİNLE KUTLAMAK İSTEDİK. BU ETKİNLİĞE GİDERKEN PEK ÇOK DUYURU YAPTIK. İŞTE ÜÇ BÜYÜK DUYURU: PAYDAY DOĞUM GÜNÜ YARIŞMASINI DUYURDUK, STEAM’DE RESMÎ PAYDAY 2 GRUBUNA KATILARAK ALINABİLEN RUS AYI \"MARK\" MASKESİNİ YAYINLADIK VE DAHA PEK ÇOK ŞEYİN YANINDA DENİZAŞIRI PAYDAY’İ TANITTIK!$NL;$NL;KUTLAMALARI KAÇIRDIYSAN ENDİŞELENME! PAYDAY, 2014’TE ÜÇ YAŞINA GİRİYOR.",
["menu_content_bonnie_desc"] = "SAVAŞIN ATEŞİNE ATILMAK BECERİ, DAYANIKLILIK VE AZIMSANMAYACAK KADAR ŞANS İSTER. BAZILARI BUNLARA DOĞUŞTAN SAHİPTİR. THE BONNIE CHARACTER PACK, PAYDAY 2’NİN DÖRDÜNCÜ ÜCRETSİZ KARAKTER PAKETİDİR VE HYPE TRAIN ETKİNLİĞİ SIRASINDA TOPLULUK TARAFINDAN AÇILMIŞTIR. SOYGUNCULAR, HAPİSTEN YENİ ÇIKMIŞ VE OYUNA DÖNMEK İSTEYEN İSKOÇ BANKA SOYGUNCUSU BONNIE OLARAK OYNAYABİLİR. PAKET; KUMARBAZ AVANTAJ DESTESİNİ, BONNIE’NİN MASKESİNİ, RIVERTOWN GLEN BOTTLE’I VE JOCELİNE O/U 12G POMPALI TÜFEĞİNİ İÇERİR. KARAKTER, SPRİNG BREAK ETKİNLİĞİNDE YAYINLANMIŞTIR VE TÜM OYUNCULARIMIZ İÇİN TAMAMEN ÜCRETSİZDİR.",
["menu_content_born_date"] = "16 HAZ 2016",
["menu_content_born_desc"] = "THE BIKER HEIST PACK, PAYDAY 2’NİN 34. PAKETİDİR. BİR MOTOSİKLET ÇETESİNİ KARŞISINA ALMAK HER ZAMAN İYİ BİR FİKİR DEĞİLDİR. AMA BAZEN NAKİT PARANIN CAZİBESİ EN TECRÜBELİ SUÇLUNUN BİLE MUHAKEMESİNİ BOZABİLİR. BU DA PAYDAY GANG EKİBİNİ RUST’IN ESKİ KULÜP BİNASINA, SONUNDA KENDİLERİNİ HIZLA GİDEN BİR TRENDE BULACAKLARI BİR İNTİHAR GÖREVİNE GÖTÜRÜYOR! PAKETTE AYRICA CR 805B SMG, ÖLÜMCÜL BİR THROWABLE AXE, DÖRT MASKE, DESENLER, MALZEMELER VE YEPYENİ BAŞARIMLAR VAR.",
["menu_content_bsides_desc"] = "B-SİDES SOUNDTRACK, OVERKILL'İN ÜNLÜ BESTECİSİ SİMON VİKLUND TARAFINDAN HAZIRLANAN BİR MÜZİK DLC'SİDİR. PAYDAY İÇERİKLERİNİ DUYURAN FRAGMANLARDA VE İNTERNET SİTELERİNDE YER ALMIŞ 14 PARÇA İÇERİR! TIPKI PAYDAY 2: THE OFFICIAL SOUNDTRACK DLC GİBİ B-SİDES SOUNDTRACK DE YENİ MÜZİKLER HAZIRLANDIKÇA SÜREKLİ GÜNCELLENECEK. YALNIZCA FRAGMANLARDA VE İNTERNET SİTELERİNDE DEĞİL, PAYDAY İLE İLGİLİ DİĞER İÇERİKLERDE KULLANILAN MÜZİKLER DE EKLENECEK.$NL;$NL;SİMON, DÜNYANIN DÖRT BİR YANINDAKİ HAYRANLARIN İSTEĞİ ÜZERİNE \"I WILL GIVE YOU MY ALL\" PARÇASININ BİR ZİL SESİNİ DE BONUS OLARAK EKLEDİ!",
["menu_content_cane_date"] = "10 ARA 2015",
["menu_content_cane_desc"] = "ÜÇÜNCÜ GELENEKSEL OVERKILL NOEL SOYGUNUYLA SEZONU KUTLA. GEÇEN YIL VLAD’IN SARHOŞ KAYINBİRADERİNİ KURTARMASINA VE DAHA DA ÖNEMLİSİ, BİR YIĞIN KOKAİNİ GERİ ALMASINA YARDIM ETTİN. VLAD YİNE MUTLULUK TOZUNUN PEŞİNDE. SENİ ESKİ BİR FABRİKAYA YOLLUYOR. BURASI NOEL BABA’NIN ATÖLYESİ GİBİ SÜSLENMİŞ; HEDİYE YAPAN ELFLER BİLE VAR. AMA BU HEDİYELER ÇOCUKLAR İÇİN DEĞİL. YANİ BU ADAMLARI VLAD İÇİN HEDİYE YAPMAYA ZORLAMALISIN. SANTA'S WORKSHOP SOYGUNU TAMAMEN ÜCRETSİZ. OVERKILL OLARAK SANA MUTLU NOELLER DİLİYORUZ!",
["menu_content_character_pack_clover_date"] = "16 ARA 2014",
["menu_content_character_pack_clover_desc"] = "DİAMOND SOYGUNU DAHA İNCE BİR DOKUNUŞ GEREKTİRİYOR OLABİLİR. BİRAZ ZARİF USTALIK. KADIN ELİ DE DİYEBİLİRSİN... THE CLOVER CHARACTER PACK DLC, PAYDAY 2’NİN 14. DLC PAKETİ VE ÜÇÜNCÜ KARAKTER PAKETİDİR. SOYGUNCULAR İRLANDALI CLOVER OLARAK OYNAYABİLİR. PAKET CLOVER’IN YANI SIRA HIRSIZ AVANTAJ DESTESİNİ, CLOVER’IN MASKESİNİ, CLOVER’S SHİLLELAGH VE QUEEN’S WRATH RİFLE SİLAHLARINI İÇERİR.",
["menu_content_character_pack_dragan_date"] = "22 OCA 2015",
["menu_content_character_pack_dragan_desc"] = "DRAGAN, ABD’DE BİR GÖREV YÜRÜTEN BUTCHER’IN SIRDAŞIDIR. BALKANLARDA YOZLAŞMIŞ BİR AJAN OLARAK ÇALIŞTIKTAN SONRA, BUTCHER İLE BAIN ARASINDAKİ BİR ANLAŞMAYLA ONA YENİ BİR KİMLİK VE KÖTÜ ŞÖHRETLİ PAYDAY GANG EKİBİNDE YER VERİLDİ. SUÇ AÇISINDAN ALTIN FIRSATLAR ÜLKESİ AMERİKA’DA YENİ BİR HAYAT. BELKİ ORADA HER ŞEY FARKLI OLURDU. THE DRAGAN CHARACTER PACK, PAYDAY 2’NİN 16. DLC PAKETİ VE DÖRDÜNCÜ KARAKTER PAKETİDİR. SOYGUNCULAR HIRVAT DRAGAN OLARAK OYNAYABİLİR. PAKET DRAGAN’IN YANI SIRA SIZMA UZMANI AVANTAJ DESTESİNİ, DRAGAN’IN MASKESİNİ, MESARİ’S CLEAVER VE LİON’S ROAR RİFLE SİLAHLARINI İÇERİR.",
["menu_content_character_pack_sokol_date"] = "25 HAZ 2015",
["menu_content_character_pack_sokol_desc"] = "RUSYA DOĞUMLU SOKOL’UN, STP BOMBERS TAKIMININ MÜCADELECİ BİR HOKEY OYUNCUSU OLARAK PARLAK BİR GELECEĞİ VARDI. AMA BU BİR PARAVANDI. MAÇ ARALARINDA KUMARHANE SOYAN SOKOL, MOSKOVA’DAN MİNSK’E KADAR ARKASINDA BOŞALTILMIŞ KASALAR BIRAKIYORDU. SONUNDA RUS POLİSİ PEŞİNE DÜŞTÜ. SOKOL KAÇTI AMA BAĞIMSIZ SOYGUNCU OLARAK GEÇİRDİĞİ GÜNLERİN SONUNA GELDİĞİNİ BİLİYORDU. KİMLİĞİNİ ÇÖZEBİLECEK KAYNAK VE ÖNGÖRÜYE SAHİP BAŞKA TEK KİŞİ VARDI: BAIN. SOKOL’A PAYDAY GANG EKİBİNDE BİR YER VE HAYATININ SOYGUNU İÇİN LAS VEGAS’A BİR BİLET TEKLİF EDİLDİ. THE SOKOL CHARACTER PACK, PAYDAY 2’NİN 25. DLC PAKETİ VE BEŞİNCİ KARAKTER PAKETİDİR. BU PAKETİ ALDIĞINDA RUS BEYİN SOKOL OYNANABİLİR BİR KARAKTER OLUR. PAKET AYRICA ÖĞÜTÜCÜ AVANTAJ DESTESİNİ, SOKOL’UN MASKESİNİ VE VALKYRIA TÜFEĞİNİ İÇERİR.",
["menu_content_charliesierra_date"] = "16 ARA 2013",
["menu_content_charliesierra_desc"] = "THE CHARLIE SANTA HEIST, PAYDAY 2’NİN İLK GELENEKSEL OVERKILL NOEL SOYGUNUDUR. OYUNCULAR, WASHINGTON D.C.’NİN DIŞ MAHALLELERİNDE COUNTERSTRİKE: GLOBAL OFFENSİVE HARİTASINDAN ESİNLENEN GO BANK’İ SOYARAK KLASİK BİR BANKA İŞİ YAPAR.$NL;$NL;BU SOYGUN OYUNCULARIMIZ İÇİN TAMAMEN ÜCRETSİZDİR. AYRICA TOPLULUK İÇİN ÜCRETSİZ BİR SİLAH NİŞANGÂHI VE TABİİ Kİ BİR NOEL BABA MASKESİ SUNAR. DAHA İYİ BİR NOEL HEDİYESİ OLABİLİR Mİ? BİZCE OLAMAZ. OVERKILL OLARAK MUTLU NOELLER DİLİYORUZ!",
["menu_content_chico_date"] = "15 ARA 2016",
["menu_content_christmas_2014_date"] = "4 ARA 2014",
["menu_content_christmas_2014_desc"] = "THE WHITE XMAS HEIST, PAYDAY 2’NİN İKİNCİ GELENEKSEL OVERKILL NOEL SOYGUNUDUR. OYUNCULAR, BOL MİKTARDA SAF KOLOMBİYA KOKAİNİ TAŞIYAN UÇAĞINI DÜŞÜREN VLAD’IN BOSNALI NORVEÇLİ PİLOT KAYINBİRADERİNİ KURTARMASINA YARDIM EDER. YALNIZCA ÇATIŞMALI OYNANAN BU SOYGUNDA OYUNCULAR, SARHOŞ PİLOTA EŞLİK EDİP HAYATTA ÇIKMASINI SAĞLARKEN YANLARINA OLABİLDİĞİNCE ÇOK DEĞERLİ EŞYA ALMALIDIR.$NL;$NL;BU SOYGUN OYUNCULARIMIZ İÇİN TAMAMEN ÜCRETSİZDİR. AYRICA ÜCRETSİZ BİR SİLAH, TOPLULUĞUN YAPTIĞI DÖRT FARKLI MASKE VE GİZLİ ÖZEL BİR MASKE SUNAR! PİLOTU DA TANIYOR OLABİLİRSİN. ;) OVERKILL OLARAK MUTLU NOELLER DİLİYORUZ!",
["menu_content_christmas_date"] = "19 ARA 2013",
["menu_content_christmas_desc"] = "A MERRY PAYDAY CHRISTMAS SOUNDTRACK, PAYDAY 2’NİN DÖRDÜNCÜ DLC PAKETİ VE YAYINLANAN İKİNCİ MÜZİK ALBÜMÜDÜR. PETE GOLD, TATİL SEZONUNU ŞARKILARLA KARŞILAMAK İÇİN \"YE OLDE HOXTON\" OLARAK GERİ DÖNÜYOR. AMA PEK ÇOK SORU HÂLÂ YANITSIZ: NEREDEYDİ? NEDEN ARTIK PAYDAY GANG ÜYESİ DEĞİL? GERİ DÖNECEK Mİ? KİMSE BİLMİYOR.$NL;$NL;HA, ÜÇ YENİ NOEL BABA MASKESİ VE HEDİYE EDEBİLECEĞİN EK MÜZİK ALBÜMÜ KOPYALARI ALDIĞINI SÖYLEMİŞ MİYDİK? GERÇEKTEN! OVERKILL OLARAK MUTLU TATİLLER DİLİYORUZ!",
["menu_content_coco_desc"] = "THE JIMMY CHARACTER PACK, PAYDAY 2’NİN 8. KARAKTER PAKETİDİR. SOYGUNCULAR, SIRA DIŞI JIMMY OLARAK OYNAYABİLİR. SINIR TANIMAZ, HİÇBİR SÖZLEŞMEYİ GERİ ÇEVİRMEZ VE HER GÜNÜNÜ SON GÜNÜYMÜŞ GİBİ YAŞAR. SADIKTIR VE EKİBE HARİKA BİR KATKI OLDUĞUNU KANITLAMIŞTIR. PAKET, JIMMY’NİN YANI SIRA MANYAK AVANTAJ DESTESİNİ, JIMMY’NİN MASKELERİNİ, SPECİALİST BIÇAKLARINI VE PAYDAY 2’YE ÇİFT HAFİF MAKİNELİ SİLAH KULLANMA İMKÂNI GETİREN HEATHER SMG’Yİ İÇERİR.",
["menu_content_complete_overkill_pack_desc"] = "YALNIZCA 50.000 KOPYAYLA SINIRLI OLAN COMPLETELY OVERKILL PACK, PAYDAY GANG'İN İLK EKİP ÜYELERİNE AİT, ÖZEL OLARAK DEĞİŞTİRİLMİŞ 4 MASKE İÇERİR. BU MASKELER, KLASİK ASILLARININ GELİŞMİŞ SÜRÜMLERİDİR. BÜYÜK ÖLÇÜDE DEĞİŞTİRİLMİŞ OLSALAR DA ÖZGÜN MASKELERİN CAZİBESİNİ KORURLAR. PAKET AYRICA İLERLEYEN BİR TARİHTE AÇIKLANIP KİLİDİ AÇILACAK GİZLİ BİR ÖZEL EŞYA DA İÇERİR.",
["menu_content_crimefest_date"] = "16 EKİ 2014 - 27 EKİ 2014",
["menu_content_crimefest_desc"] = "EKİM AYINDA OVERKILL EKİBİ, PAYDAY’İN 3 YAŞINA GİRİŞİNİ 16-27 EKİM ARASINDA 12 GÜN SÜREN CRİMEFEST İLE KUTLADI. EN AZ 7 OYUN İÇİ GÜNCELLEME, HEPSİ ÜCRETSİZ OLARAK YAYINLANDI; GELECEK İÇERİKLERLE İLGİLİ HABERLER DE PAYLAŞILDI. AYRICA STOCKHOLM’DEKİ MONSTER ENERGY DREAMHACK STUDİO’DA CREATURES İLE 2 SAATLİK CRİMEFEST CANLI YAYININI YAPTIK. OLD HOXTON, JOHN WICK VE HOXTON BREAKOUT SOYGUNU ETKİNLİK SIRASINDA YAYINLANDI. SON OLARAK STORE.OVERKİLLSOFTWARE.COM ADRESİNDEKİ ÜRÜN MAĞAZAMIZIN KAPILARINI AÇTIK.",
["menu_content_deathwish_date"] = "27 ŞUB 2014",
["menu_content_deathwish_desc"] = "THE DEATH WISH GÜNCELLEMESİ, PAYDAY 2’NİN İLERİ SEVİYEDEKİ OYUNCULARA YÖNELİK İKİNCİ GÜNCELLEMESİDİR. OYUNCULARIN EN CİDDİ SOYGUNCULARI BİLE TERLETİP KÂBUS GÖRMELERİNE YOL AÇAN YENİ DEATH WISH ZORLUĞUNU DENEMESİNİ SAĞLAR. ELİTE BULLDOZER VE GENSEC ELİTE SWAT ADLI İKİ YENİ DÜŞMAN TÜRÜ EKLER. BELİRLİ BİR ZORLUKTA TÜM SOYGUNLARI TAMAMLAMAYA CESARET EDENLER İÇİN YENİ MASKELER DE VARDIR. BUNLARA 35 YENİ BAŞARIM VE PEK ÇOK BAŞKA DÜZELTME VE ÖZELLİK EKLENDİĞİNDE, SUÇ KARİYERİNİN ZİRVESİNDEKİLERE YARAŞIR BİR GÜNCELLEME ORTAYA ÇIKAR.",
["menu_content_diamond_store_date"] = "14 EYL 2013",
["menu_content_diamond_store_desc"] = "ELMAS SOYGUNU ZAMANI! THE DIAMOND STORE HEIST, PAYDAY 2 İÇİN YAYINLANAN İLK ÜCRETSİZ SOYGUNDUR. OYUNCULAR WASHINGTON D.C. MERKEZİNDEKİ ŞIK BİR ELMAS DÜKKÂNINI SOYABİLİR. BURASI LÜKS BİR KUYUMCUDUR AMA İÇERİDE ÇOĞUNLUKLA ELMAS VARDIR VE BAIN HEPSİNİ İSTİYOR. DİKKATLİ OL; VİTRİNLERE BAĞLI ALARMLAR VAR. ZOR OLACAK AMA PAYDAY GANG İYİ BİR MEYDAN OKUMAYI SEVER! $NL;$NL;TÜM SOYGUNCULAR, DESENLERİ VE MALZEMELERİYLE BİRLİKTE DÖRT YENİ MASKENİN TADINI ÇIKARABİLİR. BU GÜNCELLEMEYLE TİTANYUM KASALARI VE KESKİN NİŞANCI ILIJA’YI DA TANITTIK.",
["menu_content_dragon_date"] = "27 AĞU 2015",
["menu_content_dragon_desc"] = "THE YAKUZA CHARACTER PACK, PAYDAY 2’NİN 27. DLC PAKETİ VE 6. KARAKTER PAKETİDİR. JAPON SOYGUNCU JIRO’YU; KATANA’SINI, 6 MODİFİKASYONLU MICRO UZI HAFİF MAKİNELİ SİLAHINI VE 2 MASKEYİ SUNAR. KÜÇÜK YAŞTA YETİM KALAN JIRO, JAPON SUÇ DÜNYASINA GİRİP HIZLA YÜKSELDİ. JIRO YAŞI İLERLEDİKÇE PATRONUNUN KIZINA ÂŞIK OLDU VE KLANIN GÖZÜNDEN DÜŞTÜ. İHANETE UĞRAYIP ÖLÜME TERK EDİLEN JIRO, UZUN BİR HAPİS CEZASINA BAŞLADI; KARISI VE OĞLU ESKİ YAKUZA KLANININ İNSAFINA KALDI. JIRO CEZASINI BİTİRDİĞİNDE KARISININ ÖLDÜĞÜNÜ VE OĞLU KENTO’NUN KAYBOLDUĞUNU ÖĞRENDİ. ÖFKEYLE DOLUP ESKİ KLANINA TEK BAŞINA SALDIRDI. ESKİ PATRONUNU ÖLDÜRDÜĞÜNDE JIRO, OĞLUNUN ABD’DE OLDUĞUNU VE BAIN ADLI BİR ADAMLA BAĞLANTI KURMASI GEREKTİĞİNİ ÖĞRENDİ.",
["menu_content_election_day_desc"] = "THE ELECTION DAY HEIST, PAYDAY 2’NİN ÜÇÜNCÜ ÜCRETSİZ SOYGUN GÜNCELLEMESİDİR. SOYGUNCULAR YOZLAŞMIŞ SİYASETÇİ ELEPHANT’TAN ELECTION DAY ADLI YENİ BİR SÖZLEŞME ALABİLİR. ELEPHANT’IN ADAMI BOB MCKENDRİCK’İ BELEDİYE BAŞKANLIĞINA TAŞIMAK İÇİN OYLAMA MAKİNELERİNİ BULMALIDIRLAR. SONRA SONUCU DEĞİŞTİRMEK ÜZERE MAKİNELERİ HACKLEMELERİ GEREKİR. SON OLARAK ŞÜPHELERİN THE ELEPHANT’A YÖNELMEDİĞİNDEN EMİN OLMALIDIRLAR. YENİ ELECTION DAY SOYGUNUYLA BİRLİKTE BÜYÜK BİR GİZLİLİK GÜNCELLEMESİ GELİR. STEAM’DE OFFİCİAL PAYDAY 2 COMMUNİTY GRUBUNA KATILAN HERKESE CHIMANO CUSTOM TABANCA DA ÜCRETSİZ VERİLİR. SON OLARAK OYUNCULARIN AÇABİLECEĞİ 10 YENİ BAŞARIM VARDIR.",
["menu_content_gage_pack_assault_date"] = "4 EYL 2014",
["menu_content_gage_pack_assault_desc"] = "THE GAGE ASSAULT PACK DLC, PAYDAY 2’NİN ONUNCU DLC PAKETİDİR. A PLANI MÜMKÜN OLMADIĞINDA PAYDAY GANG EKİBİNE BİR TAARRUZ CEPHANELİĞİ EKLER.$NL;$NL;ÜÇ TAARRUZ TÜFEĞİ, DÖRT YENİ YAKIN DÖVÜŞ SİLAHI, GERİ DÖNEN GL40 BOMBA ATAR VE PEK ÇOK MODİFİKASYON SENİ UZUN SÜRE EĞLENDİRECEK. KİŞİSELLEŞTİREBİLECEĞİN DESEN VE MALZEMELERİYLE DÖRT YENİ SÜPER KÖTÜ MASKESİ DE SENİN. ORTALIĞI HAREKETLENDİRMEK İÇİN YAKIN DÖVÜŞ SİLAHLARINA GİZLENEBİLİRLİK ÖZELLİĞİ GELİYOR. CESARETİNİ SINAYACAK 10 YENİ BAŞARIM DA OYUNA EKLENDİ.",
["menu_content_gage_pack_date"] = "05 ARA 2013",
["menu_content_gage_pack_desc"] = "THE GAGE WEAPON PACK #01, PAYDAY 2’NİN ÜÇÜNCÜ DLC PAKETİDİR. PARÇA TESİRLİ EL BOMBALARI PAYDAY SERİSİNE İLK KEZ GİRİYOR VE ORTALIĞI HAREKETLENDİRECEKLERİ KESİN. YENİ EL BOMBASI ÇANTASI DESTEĞİYLE OYUNCULAR SOYGUNLARDA EL BOMBALARINI PAYLAŞABİLİR.$NL;$NL;ÜÇ YENİ SİLAH EKLENDİ. OYUNCULAR ARTIK TÜM TAM OTOMATİK SİLAHLARDA TEKLİ VE OTOMATİK ATIŞ ARASINDA GEÇİŞ YAPABİLİR. YENİ DESEN VE MALZEMELERİN YANINDA DÖRT YENİ HAYVAN MASKESİ DE EKLENDİ.",
["menu_content_gage_pack_historical_date"] = "13 KAS 2014",
["menu_content_gage_pack_historical_desc"] = "THE GAGE HISTORICAL PACK DLC, PAYDAY 2’NİN 12. DLC PAKETİDİR VE PAYDAY GANG EKİBİNE ÇEŞİTLİ TARİHÎ SİLAHLAR EKLER.$NL;$NL;BİR KESKİN NİŞANCI TÜFEĞİ, BİR TABANCA, BİR HAFİF MAKİNELİ SİLAH, BİR HAFİF MAKİNELİ TÜFEK, DÖRT YENİ YAKIN DÖVÜŞ SİLAHI, SÜNGÜ ÖZELLİĞİ VE NOSTALJİYE DOYMAN İÇİN PEK ÇOK SİLAH MODİFİKASYONU. KİŞİSELLEŞTİREBİLECEĞİN DESEN VE MALZEMELERİYLE DÖRT ESKİ, TOZLU MASKE DE EKLENDİ. GERÇEKTEN YÜREKLİ MİSİN YOKSA KAÇAN BİR KORKAK MI, GÖRMEK İÇİN 5 YENİ BAŞARIM DA GELDİ.",
["menu_content_gage_pack_jobs_date"] = "10 NİS 2014",
["menu_content_gage_pack_jobs_desc"] = "GAGE’İN MALLARINI PİYASAYA NASIL SÜRDÜĞÜNÜ HİÇ MERAK ETTİN Mİ? İŞTE ÖĞRENME FIRSATIN! THE GAGE MOD COURIER, PAYDAY 2’NİN BEŞİNCİ DLC PAKETİDİR. GAGE, D.C.’NİN DÖRT BİR YANINA DAĞILMIŞ KÜÇÜK PAKETLER HÂLİNDEKİ SİLAH MODİFİKASYONU SEVKİYATLARINI TOPLAMASINA YARDIM ETMENİ İSTİYOR. TEK YAPMAN GEREKEN ONLARI BULUP ALMAK. KARŞILIĞINDA SANA PAY DÜŞECEK; KÂRDAN DEĞİL, MALLARDAN!$NL;$NL;GAGE İŞLERİNE BAĞLI 10 BAŞARIMI DA EKLEYİNCE SUÇ DÜNYASININ EN İYİ KURYESİ OLMAYA HAZIRSIN.",
["menu_content_gage_pack_lmg_date"] = "30 OCA 2014",
["menu_content_gage_pack_lmg_desc"] = "GAGE WEAPON PACK #02, PAYDAY 2 İÇİN ÇIKAN DÖRDÜNCÜ DLC PAKETİDİR. CLOAKER, TÜM SUÇLULARIN YÜREĞİNE KORKU SALMAK İÇİN SERİYE GERİ DÖNÜYOR. ANCAK GAGE'İN BUNA KARŞI MÜKEMMEL BİR İLACI VAR: HAFİF MAKİNELİ TÜFEKLERİ GERİ GETİRİYOR VE ONLARLA SAVAŞABİLMENİZ İÇİN YAKIN DÖVÜŞ SİLAHLARINI SUNUYOR. OYUNCULAR, HAFİF MAKİNELİ TÜFEKLERLE YIKICI SALDIRILAR DÜZENLEYEREK BİRBİRLERİNE KORUMA ATEŞİ SAĞLAYABİLİR.$NL;$NL;OYUNCULARIN CEPHANELİĞİNE ÜÇ HAFİF MAKİNELİ TÜFEK VE DÖRT BIÇAK EKLENİYOR. AYRICA GAGE'İN KOLEKSİYONUNDAN DÖRT YENİ MASKE, YENİ DESENLER VE MALZEMELER DE GELİYOR.",
["menu_content_gage_pack_shotgun_date"] = "3 TEM 2014",
["menu_content_gage_pack_shotgun_desc"] = "THE GAGE SHOTGUN PACK DLC, PAYDAY 2’NİN DOKUZUNCU DLC PAKETİDİR VE GAGE’İN SEVDİĞİ POMPALILARI OYUNCUNUN CEPHANELİĞİNE EKLER. KULLANDIĞIN MÜHİMMAT TÜRÜNE GÖRE POMPALI SAÇMALARI ZIRH DELEBİLİR VEYA PATLAYICI OLUP RAKİPLERİNİ SERSEMLETEBİLİR.$NL;$NL;OYUNCUNUN USTALAŞABİLECEĞİ ÜÇ POMPALI, DÖRT YENİ MÜHİMMAT TÜRÜ, SİLAH MODİFİKASYONLARI, DÖRT YENİ MASKE, DESENLER, MALZEMELER VE POMPALI ODAKLI 12 BAŞARIM.",
["menu_content_gage_pack_snp_desc"] = "THE GAGE SNIPER PACK DLC, PAYDAY 2’NİN ALTINCI DLC PAKETİDİR VE OYUNCUNUN CEPHANELİĞİNE GÜÇLÜ KESKİN NİŞANCI TÜFEKLERİ EKLER. KESKİN NİŞANCI TÜFEĞİ MERMİLERİ ZIRH DELİCİDİR; YANİ DUVAR GİBİ NESNELERİN İÇİNDEN GEÇEBİLİRLER. TEK MERMİ BİRDEN FAZLA DÜŞMANI BİLE DELEBİLİR.$NL;$NL;ÜÇ KESKİN NİŞANCI TÜFEĞİ, SİLAH MODİFİKASYONLARI, DÖRT YENİ MASKE, DESENLER VE MALZEMELER. AYRICA ALTIN AK.762 TÜFEĞİ, 17 BAŞARIM VE OYUNCU ENVANTERİNDEKİ SİLAHLARLA MASKELERİ TAŞIMA VE YENİDEN ADLANDIRMA GİBİ ÜCRETSİZ YENİLİKLER.",
["menu_content_gordon_date"] = "24 EYL 2015",
["menu_content_gordon_desc"] = "BİRİSİ HAREKETE GEÇMEDEN THE PAYDAY GANG EKİBİNİN SUÇ SERİSİ SONSUZA DEK SÜREMEZDİ. MAYOR MCKENDRİCK, ONLARLA İŞİ KÖKTEN HALLETMESİ İÇİN COMMİSSİONER GARRETT’I GÖREVLENDİRDİ. İLK HAMLESİ, GÜVENDİĞİ ASTLARINDAN CAPTAIN WINTERS’I SAHADAKİ POLİSLERE YARDIM ETMEK ÜZERE GÖNDERMEK OLDU. WİNTERS MORALLERİNİ VE DAYANIKLILIKLARINI ARTIRACAK. ÇETE DE BU GELİŞMELER SIRASINDA BOŞ DURMADI; FBI’IN KENDİLERİ HAKKINDA GERÇEKTEN NELER BİLDİĞİNE ERİŞMEK İÇİN İÇERİ BİR ADAM YERLEŞTİRDİ. ARTIK HER ŞEYE ERİŞİMLERİ VAR: SİLAH VE SUÇ İSTATİSTİKLERİNİ İÇEREN PROFİLLERİ, COMMİSSİONER GARRETT’IN SORUŞTURMASI VE FBI’IN İÇ YAZIŞMALARI! BAIN, CRIME.NET VERİTABANINI DA GÜNCELLEDİ; ÇETENİN EKİPMAN VE UZMANLIKLARINA ERİŞMEK İÇİN YENİ VE ŞIK BİR YOLU VAR. BÜTÜN BU İÇERİK TAMAMEN ÜCRETSİZ!",
["menu_content_grv_desc"] = "GRV AÇIKLAMASI",
["menu_content_halloween_2014_date"] = "30 EKİ 2014 - 4 KAS 2014",
["menu_content_halloween_2014_desc"] = "TAK TAK. KİM O? CEHENNEMDEN GELEN BAŞSIZ TITAN BULLDOZER! İKİNCİ GELENEKSEL PAYDAY CADILAR BAYRAMI ÖZEL ETKİNLİĞİNE HOŞ GELDİN! BU CADILAR BAYRAMINDA HUMBLE BUNDLE İLE GÜÇ BİRLİĞİ YAPIP İKİ YENİ VE ÖZEL CADILAR BAYRAMI MASKESİNİ ÜCRETSİZ SUNDUK. OYUNA, SALDIRI İÇİN HAZIRLANIRKEN TUHAF BİR SES DE ÇIKARAN PSYCHO KNIFE EKLENDİ. AYRICA HERKESİN MASKE YUVASI SAYISINI ARTIRDIK; BÖYLECE AYNI ANDA 72 MASKEYE SAHİP OLABİLİRSİNİZ! ÜRKÜTÜCÜ DÖRT CADILAR BAYRAMI MASKESİ DE GERİ DÖNÜP ETKİNLİK BOYUNCA ALINABİLDİ. SON OLARAK GÜVENLİ EV, YENİ BİR MİSAFİRLE KORKU FİLMİNDEN ÇIKMIŞ BİR YERE DÖNÜŞTÜ. GELECEK YIL BİR ŞEKİLDE GERİ DÖNECEK...",
["menu_content_halloween_date"] = "31 EKİ 2013 - 7 KAS 2013",
["menu_content_halloween_desc"] = "BU CADILAR BAYRAMINDA CEHENNEMİ YAŞAYACAKSIN! İLK GELENEKSEL PAYDAY CADILAR BAYRAMI ÖZEL ETKİNLİĞİ! MUAHAHA! CADILAR BAYRAMI ETKİNLİĞİ, STEAM’DE PAYDAY OFFİCİAL GRUBUNA KATILAN HERKESE INTERCEPTOR .45 TABANCAYI ÜCRETSİZ SUNDU. AYRICA TAMAMLAMAYA CESARET EDENLER İÇİN 14 YENİ BAŞARIM GETİRDİ! HERKESİN MASKE YUVASI SAYISINI DA ARTIRDIK; BÖYLECE AYNI ANDA 36 MASKEYE SAHİP OLABİLİRSİNİZ! ETKİNLİK BOYUNCA ÜRKÜTÜCÜ DÖRT CADILAR BAYRAMI MASKESİ DE ALINABİLDİ.$NL;$NL;SON OLARAK GÜVENLİ EV KORKU FİLMİNDEN ÇIKMIŞ BİR YERE DÖNÜŞTÜ. GELECEK YIL BİR ŞEKİLDE GERİ DÖNECEK...",
["menu_content_hl_miami_date"] = "30 EYL 2014",
["menu_content_hl_miami_desc"] = "HOTLINE MIAMI DLC, PAYDAY 2’NİN ON BİRİNCİ DLC PAKETİDİR VE DENNATON GAMES İLE OVERKILL’İN ORTAK ÇALIŞMASIDIR. YEPYENİ BİR SOYGUNUN, ÜÇ YENİ HAFİF MAKİNELİ SİLAHIN, BİR DOLU MODİFİKASYONUN VE BEŞ YENİ YAKIN DÖVÜŞ SİLAHININ TADINI ÇIKAR. HEPSİ HOTLINE MIAMI’DEN ESİNLENDİ. PAKETE DÖRT MASKE DÂHİLDİR; STEAM’DE HOTLINE MIAMI’YE SAHİPSEN DÖRT MASKENİN DAHA KİLİDİNİ AÇABİLİRSİN. AYRICA ALTI BAŞARIM, DÖRT DESEN VE DÖRT MALZEME EKLENDİ. BAŞKALARINA ACI ÇEKTİRMEKTEN HOŞLANIYORSAN BU DLC TAM SANA GÖRE.",
["menu_content_hlm2_deluxe_desc"] = "OVERKILL VE DENNATON GAMES BİR KEZ DAHA HARİKA BİR ŞEY SUNMAK İÇİN BİRLİKTE ÇALIŞIYOR. HOTLINE MIAMI 2: WRONG NUMBER - DIGITAL SPECIAL EDITION ALDIĞINDA YANINDA EK PAYDAY 2 GANİMETİ VERİYORUZ. THE JACKET CHARACTER PACK, HOTLINE MIAMI 2: WRONG NUMBER - DIGITAL SPECIAL EDITION’IN BİR PARÇASIDIR VE PAYDAY 2’NİN BEŞİNCİ KARAKTER PAKETİDİR. SOYGUNCULAR AMERİKAN SOSYOPAT JACKET OLARAK OYNAYABİLİR. PAKET JACKET’IN YANI SIRA SOSYOPAT AVANTAJ DESTESİNİ, RİCHARD RETURN’S MASKESİNİ, CARPENTER’S DELİGHT ÇEKİCİNİ VE JACKET’S PİECE SİLAHINI İÇERİR.",
["menu_content_hlm2_desc"] = "TELESEKRETERİNE KİM MESAJ BIRAKIYOR? HOTLINE MIAMI 2: WRONG NUMBER’I SATIN ALDIĞINDA PAYDAY 2 DENEYİMİN İÇİN GÜZEL GANİMETLERİN KİLİDİ AÇILIR. BUNLAR ARASINDA HOTLINE MIAMI OYUNUNDAN 6 ÜNLÜ MASKE DE VAR. BU GÜZELLİKLERİ TAKARKEN NEDEN BİRAZ *DAHA FAZLA* DELİRMEYESİN?",
["menu_content_hope_diamond_date"] = "16 ARA 2014",
["menu_content_hope_diamond_desc"] = "THE DIAMOND HEIST DLC, PAYDAY 2’NİN 13. DLC PAKETİDİR VE DENTİST ADLI YENİ BAĞLANTININ DÖRDÜNCÜ SOYGUNUNU İÇERİR. PAYDAY GANG, BUGÜNE KADARKİ EN HEYECAN VERİCİ SOYGUNU OLAN DİAMOND SOYGUNUNDA PARLAMAYA HAZIRLANIYOR. DİAMOND EFSANESİNİ DUYMUŞSUNDUR. GENGHİS KHAN’IN BULDUĞU, ORDULARININ ÖNÜNDE TAŞINAN BİR GÖKTAŞI. KANA SUSAMIŞ KRALLARIN VE TRAJİK KRALİÇELERİN SAHİP OLDUĞU BİR TAŞ. KULAĞA KAMP ATEŞİ BAŞINDA ANLATILAN BİR HAYALET HİKÂYESİ GİBİ GELEBİLİR. LANETLER, EFSANELER... DELİLİK, ÖLÜM. DİAMOND SOYGUNUYLA BİRLİKTE GEÇMİŞİN FİGÜRLERİNDEN ESİNLENEN DÖRT YENİ MASKEYE, BUNLARIN MALZEME VE DESENLERİNE DE SAHİP OLACAKSIN. İŞLERİ DAHA DA İLGİNÇ KILMAK İÇİN 7 YENİ BAŞARIM DA EKLENDİ.",
["menu_content_hoxton_char_date"] = "27 EKİ 2014",
["menu_content_hoxton_char_desc"] = "BENİ ÖZLEDİNİZ Mİ, DALLAMALAR? THE OLD HOXTON CHARACTER PACK, PAYDAY 2’NİN İKİNCİ ÜCRETSİZ KARAKTER PAKETİDİR. SOYGUNCULAR, PAYDAY GANG EKİBİNİN CENTİLMENİ OLD HOXTON OLARAK OYNAYABİLİR. OLD HOX’UN YANI SIRA DÜZENBAZ AVANTAJ DESTESİNİ, HOXTON REBORN MASKESİNİ, NOVA’S SHANK’İ VE PREDATOR 12G POMPALI TÜFEĞİNİ İÇERİR. BU KARAKTER PAKETİ, 44. GÜNCELLEMENİN BİR PARÇASIYDI VE OYUNCULARIMIZ İÇİN TAMAMEN ÜCRETSİZDİR.",
["menu_content_hoxton_job_date"] = "27 EKİ 2014",
["menu_content_hoxton_job_desc"] = "#FREEHOXTON ZAMANI. THE HOXTON BREAKOUT HEİST, PAYDAY 2’NİN BEŞİNCİ ÜCRETSİZ SOYGUN GÜNCELLEMESİDİR. THE DENTIST, HOXTON’IN YENİDEN YARGILANMASINI SAĞLADI VE ONU SEN ÇIKARACAKSIN! YALNIZCA ÇATIŞMALI OYNANAN BU SOYGUN; OYNANABİLİR OLD HOXTON KARAKTERİNİ, \"HOXTON REBORN\" MASKESİNİ VE 4 YENİ BAŞARIMI İÇERİR. BU SOYGUN, 44. GÜNCELLEMENİN BİR PARÇASIYDI VE OYUNCULARIMIZ İÇİN TAMAMEN ÜCRETSİZDİR.",
["menu_content_hw_boxing_date"] = "02 OCA 2015",
["menu_content_hw_boxing_desc"] = "MUTLU YILLAR, SOYGUNCULAR! OVERKILL SOFTWARE VE STARBREEZE STUDİOS’TAKİ HEPİMİZ HARİKA BİR TATİL GEÇİRMİŞ OLMANIZI İÇTENLİKLE UMUYOR, SİZE MUTLU, SAĞLIKLI VE BEREKETLİ BİR 2015 DİLİYORUZ. AMA ÇANLAR HENÜZ SUSMADI. 2015’İNİZİ BÜYÜK BİR ZAFERLE BAŞLATMAYA HAZIRIZ. HAKEM PUANLARIYLA KIL PAYI KAZANILMIŞ BİR ZAFER DEĞİL; ÜÇ RAUNTTA KESİN NAKAVT! YENİ YILA BAŞLARKEN SİZE CHAMP MASKESİNİ VE OVERKILL BOKS ELDİVENLERİNİ SUNUYORUZ. DAHA ÖNCE DUYURDUĞUMUZ GİBİ PAYDAY 2 ÜZERİNDE 2016 BOYUNCA DA ÇALIŞMAYA DEVAM EDECEĞİZ. SİZ SOYGUN YAPMAK İSTEDİĞİNİZ SÜRECE BİZ DE MÜMKÜN OLAN EN İYİ SOYGUN DENEYİMİNİ SUNMAYI AMAÇLIYORUZ.",
["menu_content_infamy_2_0_desc"] = "KÖTÜ ŞÖHRET 2.0, PAYDAY 2’NİN İLERİ SEVİYEDEKİ OYUNCULARA YÖNELİK İKİNCİ GÜNCELLEMESİDİR. OYUNCULAR YENİ KÖTÜ ŞÖHRET SİSTEMİNİ KEŞFEDEBİLİR; BECERİ AĞACI BONUSLARI, MASKELER, MALZEMELER VE DESENLER GİBİ ÖDÜLLER KAZANABİLİR.$NL;$NL;ÜCRETSİZ KÖTÜ ŞÖHRET 2.0 GÜNCELLEMESİYLE BİR ADIM DAHA İLERİ GİDİYORUZ: 20 YENİ KÖTÜ ŞÖHRET RÜTBESİ VE BAŞARIMIN YANI SIRA BAŞKA ÖDÜLLER VE AÇILABİLİR İÇERİKLER EKLİYORUZ. EN KÖTÜ ŞÖHRETLİ SUÇLU OLMA MEYDAN OKUMASINI KABUL EDECEK MİSİN, YOKSA PEK ÇOK KİŞİ GİBİ YARI YOLDA BAŞARISIZ OLUP SİLİNİP GİDECEK MİSİN?",
["menu_content_infamy_date"] = "22 OCA 2014",
["menu_content_infamy_desc"] = "KÖTÜ ŞÖHRET GÜNCELLEMESİ, PAYDAY 2’NİN İLERİ SEVİYEDEKİ OYUNCULARA YÖNELİK İLK GÜNCELLEMESİDİR. OYUNCULAR YENİ KÖTÜ ŞÖHRET AĞACINI KEŞFEDEBİLİR; BECERİ AĞACI BONUSLARI, MASKELER, MALZEMELER VE DESENLER GİBİ ÖDÜLLER KAZANABİLİR.$NL;$NL;KÖTÜ ŞÖHRET SAHİBİ OLMAK, 100. SEVİYENİN ÖTESİNE GEÇMEYE VE CRIME.NET’İN EN ÇOK ARANAN SUÇLULARI ARASINA GİRMEK İÇİN HER ŞEYİNDEN VAZGEÇMEYE CESARET EDENLERE GÖREDİR. MÜTHİŞ YENİ GANİMETLERİN KİLİDİNİ AÇMAK İÇİN SUÇ BASAMAKLARINI TIRMANIRKEN POLİS SENİ GÖRÜNCE DEHŞET İÇİNDE KAÇACAK, ARKADAŞLARINSA SENİ KISKANARAK İZLEYECEK.",
["menu_content_jowi_date"] = "22 EKİ 2014",
["menu_content_jowi_desc"] = "TEKİNSİZ BİR ŞEY YAKLAŞIYOR. THE JOHN WICK CHARACTER PACK, PAYDAY 2’NİN İLK ÜCRETSİZ KARAKTER PAKETİDİR. SOYGUNCULAR PAYDAY GANG EKİBİNİN KİRALIK KATİLİ JOHN WICK OLARAK OYNAYABİLİR. JOHN’IN YANI SIRA TETİKÇİ AVANTAJ DESTESİNİ, ÜÇ GÜNEŞ GÖZLÜĞÜNÜ, URSA TANTO BIÇAĞINI VE CHİMANO COMPACT TABANCAYI İÇERİR. BU KARAKTER PAKETİ, 40. GÜNCELLEMENİN BİR PARÇASIYDI VE OYUNCULARIMIZ İÇİN TAMAMEN ÜCRETSİZDİR.",
["menu_content_jukebox_date"] = "18 EYL 2014",
["menu_content_jukebox_desc"] = "THE BIG FAT MUSIC UPDATE; ÖZEL ÇALMA LİSTELERİ, SOYGUNA ÖZEL PARÇALAR, ÖZEL MENÜ MÜZİĞİ VE BİRKAÇ YENİ PARÇA GİBİ MÜZİK ÖZELLİKLERİ SUNAN ÜCRETSİZ BİR GÜNCELLEMEDİR. AYRICA PAYDAY: THE HEİST MÜZİK ALBÜMÜNE SAHİPSEN BU PARÇALAR DA HEM SOYGUNLARDA HEM MENÜLERDE KULLANILABİLİR. 2011’DEYMİŞİZ GİBİ EĞLENELİM!",
["menu_content_kenaz_date"] = "25 HAZ 2015",
["menu_content_kenaz_desc"] = "THE GOLDEN GRIN CASINO HEİST DLC, PAYDAY 2’NİN 24. DLC PAKETİDİR VE THE DENTIST’IN PAYDAY EKİBİYLE ANLAŞMASININ SON GÖREVİDİR. SOYGUNU İSTEDİĞİN GİBİ ÖNCEDEN PLANLA: ÇATIŞMAYA GİRERKEN EKİBİNİN GÜÇLÜ VE ZAYIF YANLARINA GÖRE ŞİMDİYE KADARKİ EN BÜYÜK, EN BELALI MATKABI ÖZELLEŞTİR. YA DA KUMARBAZLARIN VE MUHAFIZLARIN ARASINDA KİMLİĞİNİ GİZLEYEREK YÜRÜ; ONLAR HİÇ GELMEYECEK BİR VURGUNUN HAYALİNİ KURARKEN SEN BURUNLARININ DİBİNDEN HER ŞEYİ AL. THE GOLDEN GRIN CASINO DLC, EFSANEVİ BİR SOYGUNUN YANI SIRA 4 MASKE, 4 DESEN, 4 MALZEME, 5 BAŞARIM VE KATLANABİLİR, YÜKSEK KAPASİTELİ, SERT VURAN CAVITY 9MM RİFLE İLE GELİYOR.",
["menu_content_kosugi_desc"] = "THE SHADOW RAID HEİST, PAYDAY 2’NİN DÖRDÜNCÜ ÜCRETSİZ SOYGUN GÜNCELLEMESİDİR. SHADOW RAID SOYGUNUNDA SOYGUNCULAR, ÖZEL ASKERÎ ŞİRKET MURKYWATER’IN KATILDIĞI TÜM ÇATIŞMALARDAN ÇALDIĞI GİZLİ GANİMETLERİ SAKLADIĞI, SIKI KORUNAN BİR DEPOYA SIZIYOR. BURASI MURKYWATER BÖLGESİ OLDUĞUNDAN GÖRÜLÜRSENİZ OLABİLDİĞİNCE HIZLI KAÇMALISINIZ. SÖYLENTİYE GÖRE DEPONUN BİR YERİNDE OLAĞANÜSTÜ DEĞERLİ BİR ŞEY SAKLI.$NL;$NL;YENİ SHADOW RAID SOYGUNUYLA BİRLİKTE KORKUTUCU YENİ BİR MASKE VE ALTI YENİ BAŞARIM DA GELİYOR.",
["menu_content_mad_desc"] = "THE HARDCORE HEİSTS, PAYDAY 2’NİN 33. PAKETİDİR. PAYDAY’İN TEMEL OYNANIŞININ EN İYİ YANLARINI BİR ARAYA GETİREREK HEM GİZLİLİK HEM AKSİYON ODAKLI OYUNCULARIMIZA HİTAP EDER. \"MURKY STATION\" SOYGUNUNDA ÇETENİN, MURKYWATER’IN İŞLETTİĞİ GİZLİ BİR TREN SAHASINA SIZMASI GEREKİR. OYUNCULAR ALARMI TETİKLEMEDEN EMP BOMBASINI ELE GEÇİRMELİDİR; AKSİ HÂLDE BAŞARISIZ OLURLAR. \"BOILING POINT\" SOYGUNUNDA ÇETE, BU DÜNYA HAKKINDA BİLDİĞİMİZ HER ŞEYİ DEĞİŞTİREBİLECEK VERİLER İÇEREN GİZLİ BİR LABORATUVARI BULMAK İÇİN RUSYA’YA GİDER. AMA DİKKAT: RUS PARALI ASKERLER SİZİ DURDURMAK İÇİN ELLERİNDEN GELENİ YAPACAK. HAYATINIZ İÇİN SAVAŞMAYA HAZIR OLUN. BU İKİ YENİ SOYGUNLA BİRLİKTE YENİ WHITE STREAK TABANCASI, ELECTRICAL BRASS KNUCKLES, DÖRT MASKE, DÖRT DESEN, DÖRT MALZEME, ON BAŞARIM VE SİMON VİKLUND’DAN İKİ YENİ PARÇA GELİR.",
["menu_content_opera_desc"] = "THE SYDNEY CHARACTER PACK, PAYDAY 2’NİN 9. KARAKTER PAKETİDİR. SOYGUNCULAR ARTIK MELBOURNE’ÜN SERT MAHALLELERİNDE BÜYÜMÜŞ HEM ASİ HEM PUNK ROCKÇI SYDNEY’NİN KAOS DOLU ROLÜNÜ ÜSTLENEBİLİR. EŞİNE AZ RASTLANIR ÖFKESİYLE SUÇ DÜNYASINDA DOLAŞIRKEN İNSANLARA İHTİYAÇ DUYDUKLARI KARGAŞAYI SUNAR VE SONUNDA PAYDAY GANG EKİBİNE KATILIR. SYDNEY İLE BİRLİKTE ANARŞİST AVANTAJ DESTESİ, SYDNEY’S MASK, WİNG BUTTERFLY MELEE KNİFE VE BOOTLEG ASSAULT RİFLE GELİR.",
["menu_content_overkill_pack_desc"] = "OVERKILL PACK, PAYDAY 2 İÇİN HAZIRLADIĞIMIZ 17. DLC PAKETİDİR. SOYGUNCULARA MİNİGUN VE ROCKET LAUNCHER SİLAHLARINI, OVERKILL MASKESİNİ VE YENİ OVERKILL KAÇIŞ MİNİBÜSÜ KAPLAMASINI SUNAR. MİNİGUN İÇİN 3 SİLAH MODİFİKASYONUNUN YANI SIRA TOPLAM 10 EK BAŞARIM DA EKLENECEK. OVERKILL PACK, HYPE TRAIN ETKİNLİĞİNE BOL MİKTARDA HYPE FUEL EKLEYEREK TÜM PAYDAY 2 SAHİPLERİ İÇİN EK İÇERİK AÇMA ŞANSI SAĞLAR.",
["menu_content_pal_date"] = "11 ŞUB 2016",
["menu_content_pal_desc"] = "THE WOLF PACK DLC, PAYDAY 2’NİN 31. PAKETİDİR. PAYDAY: THE HEİST’IN SEVİLEN İKİ HARİTASINI YENİDEN CANLANDIRARAK ANILARA YOLCULUK YAPIYORUZ. \"COUNTERFEİT\" SOYGUNUNDA ÇETE, MR. MITCHELL ADLI BİRİNİN İŞLETTİĞİ KARA PARA AKLAMA İŞİNİ BOZMAK İÇİN GÜNEŞLİ FLORİDA’YA GİDER. BODHI’S POOL REPAİR TANIDIK GELDİ Mİ? \"UNDERCOVER\" SOYGUNUNDA ÇETE, BİR VERGİ MEMURUYLA BÜYÜK BİR ŞİRKET ARASINDAKİ KİRLİ ANLAŞMAYA EL KOYMAYA GİDER. ORTADA 25.000.000 $ VARDIR VE İŞLER ŞİDDETE DÖNECEKTİR. BUNUN YANINDA YENİ BİR POMPALI MEKANİZMALI BOMBA ATAR, BİR YAKIN DÖVÜŞ SİLAHI, DÖRT MASKE, DÖRT DESEN, DÖRT MALZEME VE SİMON VİKLUND’DAN İKİ YENİ PARÇA GELİR. ",
["menu_content_peta_date"] = "14 OCA 2016",
