["menu_content_pim_desc"] = "THE JOHN WICK WEAPON PACK, PAYDAY 2’NİN 35. PAKETİDİR. İLK SALDIRIYI RUSLAR YAPTI AMA SON DARBEYİ JOHN WICK VURDU. JOHN İNTİKAMINI ALMAK İÇİN SİLAHLARINI GÖMDÜĞÜ YERDEN ÇIKARDI; ONLARLA BİRLİKTE GEÇMİŞİNİ DE ÇIKARDI. ARTIK ONU CESETLERLE DOLU, KANA BULANMIŞ ESKİ YOLUNDAN YÜRÜMEKTEN HİÇBİR ŞEY ALIKOYAMAZ. JOHN’IN CEPHANELİĞİNDE CONTRACTOR TABANCASI, JACKAL HAFİF MAKİNELİ SİLAHI VE DESERTFOX KESKİN NİŞANCI TÜFEĞİ BULUNUYOR. AYRICA PAKETTE 4 MASKE, 4 MALZEME, 4 DESEN VE 4 YENİ BAŞARIM VAR!",
["menu_content_rip_date"] = "03 ARA 2015",
["menu_content_rip_desc"] = "BODHI, PAYDAY 2’NİN 7. KARAKTER PAKETİDİR. EX-PRESİDENTS ÇETESİNİN KURUCUSU OLARAK SUÇ DÜNYASININ EN BÜYÜK EFSANELERİNDEN BİRİ SAYILIR. MUMBAİ VE AVUSTURYA’DAKİ SON GÖVDE GÖSTERİLERİ BAIN’İN DİKKATİNİ ÇEKMİŞ VE ONA PAYDAY GANG EKİBİNE KATILMA DAVETİ KAZANDIRMIŞTIR. BODHI İLE BİRLİKTE PLATYPUS KESKİN NİŞANCI TÜFEĞİ, BİR MAKET BIÇAĞI, 2 MASKE VE ESKİ BAŞKAN AVANTAJ DESTESİ GELİR. OVERKILL OLARAK BODHI’Yİ PAYDAY GANG ÜYESİ OLARAK TANITMAKTAN BÜYÜK HEYECAN DUYUYORUZ.",
["menu_content_rvd_date"] = "14 ARA 2017",
["menu_content_shoutout_desc"] = "THE MELTDOWN HEİST, 11. ÜCRETSİZ SOYGUNUMUZ. BİR YIL ÖNCE BULUNDUĞUMUZ YERE GERİ DÖNÜYORUZ. AMA BU SEFER BİR ŞEY İSTEYEN GAGE DEĞİL, VLAD. AÇGÖZLÜLÜK VE DELİLİĞİN ETKİSİNDEKİ BU ÇATLAK PİÇ, SİZİ MURKYWATER WAREHOUSE’A BİR KEZ DAHA YOLLUYOR. GÜPEGÜNDÜZ, SİLAHLAR SUSMADAN. EN AĞIR SİLAHLARINI VE EN KALIN ZIRHINI GETİR; MURKYWATER ASKERLERİ VE WASHINGTON’IN EN İYİLERİ SENİ BEKLİYOR.$NL;$NL;BU GÜNCELLEMEDE AYRICA ÇEVRE BİLİNCİNE YENİ BİR ÇAĞ AÇACAK YENİ BİR MASKE VE DÖRT ZORLU YENİ BAŞARIM VAR!",
["menu_content_soundtrack_date"] = "13 AĞU 2013",
["menu_content_soundtrack_desc"] = "PAYDAY: 2 OFFICIAL SOUNDTRACK, PAYDAY 2’NİN İLK DLC PAKETİDİR. OVERKILL’İN ÜNLÜ DEHASI SİMON VİKLUND’UN BESTELEDİĞİ TÜM PAYDAY 2 PARÇALARINDAN OLUŞUR. YÜKSEK KALİTELİ MP3 VE FLAC BİÇİMLERİNDEKİ BU PAYDAY ALBÜMÜYLE KENDİNİ PAYDAY DÜNYASINA BIRAK! PAYDAY 2 BÜYÜDÜKÇE RESMÎ MÜZİK ALBÜMÜ DE BÜYÜR; YENİ PARÇALAR ÜCRETSİZ EKLENİR.$NL;$NL;PAYDAY 2 OFFICIAL SOUNDTRACK, POETRY JAM YARIŞMASI SAYESİNDE TOPLULUĞUN HAZIRLADIĞI DÖRT MASKE VE DESENİ DE İÇERİR. SON OLARAK, KENDİ PAYDAY 2 ESİNLİ MÜZİKLERİNİ YAPABİLMEN İÇİN REMİKS MALZEMELERİ DE SUNAR!",
["menu_content_springbreak_desc"] = "13-21 MART ARASINDA DÜZENLEDİĞİMİZ SPRİNG BREAK ETKİNLİĞİNDE, HYPE TRAIN SIRASINDA AÇILAN TÜM ÜCRETSİZ İÇERİKLERİ DAĞITTIK. TIPKI ÖNCEKİ YILKİ CRİMEFEST ETKİNLİĞİNDE OLDUĞU GİBİ HER GÜN YENİ BİR ŞEY YAYINLANDI. COOK OFF VE TRAİN HEİSTS SOYGUNLARINI VE YAN İŞLER ÖZELLİĞİNİ YAYINLADIK. PAYDAY GANG EKİBİNİN ONUNCU SOYGUNCUSU BONNIE’Yİ, GÜVENİLİR ÇİFT NAMLULU POMPALISIYLA BİRLİKTE TANITTIK. SWAT MİNİBÜSÜ TARETİ DÜŞMANININ GELİŞİNE ZEMİN HAZIRLADIK VE GOLDEN GRIN CASINO’NUN ÖN GÖSTERİMİNİ SUNDUK. SON OLARAK, İKİ YENİ SOYGUNLA BİRLİKTE İKİNCİ BUTCHER MOD PAKETİNİ DAĞITTIK, HOXTON REVENGE HEİST’TE MUHBİRİ KOVALADIK VE CAR SHOP HEİST’TE ARABA KULLANMAYI ÖĞRENDİK.",
["menu_content_springcleaning"] = "YENİ DP SİSTEMİ YAYINDA!",
["menu_content_springcleaning_desc"] = "PAYDAY TOPLULUĞU YİNE BAŞARDI! OVERKILL’DE DEVAM EDEN TÜM DİĞER İŞLERİN YANINDA MÜMKÜN OLDUĞUNCA ÇOK HATA DÜZELTMESİ VE İYİLEŞTİRME YAPMAYA DA ÇALIŞIYORUZ. BU SEFER BÜYÜK BİR BAHAR TEMİZLİĞİNE GİRİŞTİK VE BİRÇOĞUNU SADIK OYUNCULARIMIZIN BULDUĞU TONLARCA HATAYI DÜZELTTİK. ÜSTÜNE BİR DE OYUNA EKLEMEK İSTEDİĞİMİZ YEPYENİ BİR DP SİSTEMİ VARDI.$NL;HER ŞEYİ BİR BETA SÜRÜMÜNDE TEST ETMEK İÇİN TOPLULUKTAN YARDIM İSTEDİK VE FAZLASIYLA KARŞILIK BULDUK. 2000’DEN FAZLA OYUNCU BETAYI TEST ETMEMİZE YARDIM ETTİ. ARTIK YAYINLANMAYA HAZIR.$NL;$NL;TÜM OYUNCULARIMIZI SELAMLIYORUZ!",
["menu_content_steel_date"] = "10 EYL 2015",
["menu_content_steel_desc"] = "THE GAGE CHIVALRY PACK, PAYDAY 2’NİN 28. DLC PAKETİDİR VE TORN BANNER STUDİOS İLE OVERKILL ORTAKLIĞIYLA HAZIRLANDI! GAGE’İN SON ÇALINTI MALLARIYLA D.C.’NİN EN İYİLERİNE ORTA ÇAĞ’I YAŞAT: GREAT SWORD, MORNING STAR, BUCKLER SHIELD VE BEARDED AXE SİLAHLARININ TÜMÜ YAKIN DÖVÜŞ YUVASINA TAKILIR. UZAKTAN SAVAŞMAYI TERCİH EDİYORSAN PATLAYICI VE ZEHİRLİ SEÇENEKLERİ OLAN AĞIR ARBALETİ, HAFİF ARBALETİ VEYA KLASİK İNGİLİZ UZUN YAYINI KULLANABİLİRSİN. HER ŞEY TERS GİDERSE GÜNÜ KURTARMAK İÇİN FIRLATILABİLİR JAVELİN’E GÜVEN; TAM İKİ GÖZLERİNİN ARASINA İSABET ETTİRDİĞİNDEN EMİN OL YETER. THE GAGE CHIVALRY PACK AYRICA CHİVALRY: MEDİEVAL WARFARE OYUNUNDAN DÖRT MİĞFER, ORTA ÇAĞ TEMALI DÖRT DESEN VE MALZEME İLE DÖRT YENİ BAŞARIM İÇERİR!",
