["menu_content_the_bomb_date"] = "22 OCA 2015",
["menu_content_the_bomb_desc"] = "THE BOMB HEISTS DLC, PAYDAY 2’NİN 15. DLC PAKETİDİR VE BUTCHER ADLI YENİ BAĞLANTININ İLK İKİ SOYGUNUNU İÇERİR. BOMB İŞİNİN PARÇALARI OLAN DOCKYARD VE FOREST SOYGUNLARINDA BUTCHER’IN BAŞARILI OLMASINA YARDIM EDERKEN BOMBALAR HAVADA UÇUŞACAK. BOMB HEİSTS’İN ÇIKIŞIYLA BİRLİKTE LİON GAME LİON’IN İLK PAYDAY 2 DLC PAKETİ İÇİN NELER HAZIRLADIĞINI PAYLAŞMANIN HEYECANINI YAŞIYORUZ. OVERKILL VE LİON GAME LİON’DAKİ HERKES, YENİ İÇERİĞİ OYNADIKTAN SONRA TOPLULUĞUN NE DÜŞÜNDÜĞÜNÜ DUYMAYI SABIRSIZLIKLA BEKLİYOR! BOMB SOYGUNLARIYLA BİRLİKTE BİR YENİ TABANCA, DÖRT YENİ MASKE, DÖRT MALZEME VE DÖRT DESEN DE ALACAKSIN. EK BİR MEYDAN OKUMA İÇİN 11 YENİ BAŞARIM DA EKLENDİ.",
["menu_content_turtles_date"] = "16 TEM 2015",
["menu_content_turtles_desc"] = "THE GAGE NINJA PACK, PAYDAY 2’NİN 26. DLC PAKETİDİR VE GAGE BU PAKETTE GERİ DÖNÜYOR. DOĞU’YA YAPTIĞI YOLCULUKLARDA NİNJALARIN SAVAŞÇI KÜLTÜRÜNDEN ESİNLENİP STOĞUNU SUİKASTÇILARA UYGUN SİLAHLARLA DOLDURDU. KROSS VERTEX HAFİF MAKİNELİ SİLAHI, LEBENSAUGER .308 KESKİN NİŞANCI TÜFEĞİ VE TABANCA ARBALET GİZLİ ÖLDÜRMELER İÇİN GELİŞTİRİLDİ. ZEHİR KAPLI KUNAI KNIFE, TALONS, OKİNAWA OCTAGONAL SAİ VE EMPTY PALM KATA TARZI DÂHİL KADİM DÖVÜŞ SANATLARIYLA POLİSLERİN KALBİNE KORKU SAL. EN GÜZELİ, 10’LU PAKETLER HÂLİNDE GELEN VE YERDEN DE TOPLANABİLEN ZEHİRLİ SHURİKEN! DÖRT NİNJA ESİNLİ MASKE, DESEN VE MALZEME İLE 4 YENİ BAŞARIM DA BU ÖZENLE HAZIRLANMIŞ GAGE NINJA PACK PAKETİNDE!",
["menu_content_tutorial_date"] = "09 HAZ 2016",
