["menu_content_update100"] = "100. GÜNCELLEME",
["menu_content_update100_date"] = "02 HAZ 2016",
["menu_content_update100_desc"] = "YAZ GELDİĞİNE GÖRE 100. GÜNCELLEMEYİ YAYINLAMANIN ZAMANI GELDİ! UZUN BİR YOLCULUK OLDU VE TABİİ Kİ BU HARİKA GÜNCELLEMENİN SEVİNCİNİ KUTLAMAK İSTİYORUZ!$NL;100. GÜNCELLEMEDE TÜM STEAM TOPLULUK GRUBU ÜYELERİ YEPYENİ HEF GRENADE’E ERİŞEBİLECEK.$NL;YENİLENEN BECERİ AĞAÇLARIMIZI DA OYUNUN ANA SÜRÜMÜNE EKLEME VAKTİ GELDİ. BECERİLER BETASINA KATILIP GERİ BİLDİRİM VE FİKİRLERİNİ BİZİMLE PAYLAŞAN TÜM OYUNCULARA TEŞEKKÜR EDİYORUZ. YENİ BECERİLERİ TAMAMLARKEN BUNLARI GÖZ ÖNÜNDE BULUNDURDUK; ARTIK BETADAN ANA SÜRÜME GEÇME ZAMANI.$NL;$NL; İYİ EĞLENCELER, KASKLARI UÇURMAYA DEVAM!",
