["menu_cs_basement"] = "BODRUM",
["menu_cs_basement_desc"] = "BODRUMDA JOHN WICK BİR ATIŞ POLİGONU KURUYOR. HEMEN YANINDA WOLF’UN ATÖLYESİ VAR. ÖBÜR UÇTA SOKOL VE DRAGAN’IN SPOR SALONU VE ANTRENMAN ALANLARI BULUNUYOR. BODHI DE SÖRF TAHTALARI İÇİN BİR ATÖLYE KURMUŞ. BİR DE JACKET’IN KÖŞESİ VAR.$NL;$NL;ÇETENİN TÜM O GÜZELİM GANİMETİ SAKLADIĞI KASA DA BODRUMDA.",
