["menu_cs_daily_available"] = "$character; SANA BİR MEYDAN OKUMA SUNUYOR. KABUL ETMEK İÇİN ONU GÜVENLİ EVDE ZİYARET ET.",
["menu_cs_daily_challenge"] = "YAN İŞLER",
["menu_cs_daily_desc"] = "HER GÜN GÜVENLİ EVDE BİR SOYGUNCU SANA BİR MEYDAN OKUMA SUNAR! KABUL ETMEK İÇİN GÜVENLİ EVDE ONUNLA BULUŞ, SONRA DIŞARI ÇIKIP GEREKSİNİMLERİ YERİNE GETİR. MEYDAN OKUMAYI TAMAMLADIĞINDA ZAHMETİN KARŞILIĞINDA BİRKAÇ SİKKE VERİR.$NL;$NL;WICK, PAYDAY EKİBİNE THE CONTINENTAL ÜYELİĞİ SAĞLADI. BU YÜZDEN YAPTIĞIN HER SOYGUN İÇİN SANA SİKKE VERİYORLAR. YETERİNCE SİKKEN OLDUĞUNDA CHARLİE VE ADAMLARI GELİP BİZİM İÇİN BİRAZ TADİLAT YAPACAK VE YAPILAN HİÇBİR İŞİN KAYITLARA GEÇMEMESİNİ SAĞLAYACAK.",
