["menu_cs_ga_increased_throwables"] = "DAHA FAZLA FIRLAT",
["menu_cs_ga_increased_throwables_desc"] = "TÜM OYUNCULAR %$throwables; EK FIRLATILABİLİR SİLAH KAZANIR. (EN AZ: 1)",
["menu_cs_ga_life_steal"] = "KENDİNİ İYİLEŞTİREN",
["menu_cs_ga_life_steal_desc"] = "OYUNCULAR BİR DÜŞMAN ÖLDÜRDÜKLERİNDE BİR MİKTAR SAĞLIK YENİLER. BU ETKİ YALNIZCA $cooldown; SANİYEDE BİR GERÇEKLEŞEBİLİR.",
["menu_cs_ga_limit_reached"] = "SINIRA ULAŞILDI",
["menu_cs_ga_melee_invulnerability"] = "KISA SÜRELİ DOKUNULMAZLIK",
["menu_cs_ga_melee_invulnerability_desc"] = "OYUNCULAR, ÖZEL BİR DÜŞMANI YAKIN DÖVÜŞ SALDIRISIYLA ÖLDÜRDÜKTEN SONRA $time; SANİYELİĞİNE HASAR ALMAZ.",
["menu_cs_ga_passive_panic"] = "BİRAZ PANİK",
["menu_cs_ga_passive_panic_desc"] = "TÜM OYUNCULAR, DÜŞMANLARI PANİĞE SÜRÜKLEMEK İÇİN %$panic; ŞANS KAZANIR.",
["menu_cs_ga_quick_locks"] = "KİLİT AÇMANIN KRALI",
