["menu_cs_ga_quick_reload"] = "HIZLI DOLDURUCU",
["menu_cs_ga_quick_reload_desc"] = "TÜM OYUNCULARIN DOLDURMA SÜRESİ %$speed; AZALIR.",
["menu_cs_ga_quick_switch"] = "HIZLI DEĞİŞTİRİCİ",
["menu_cs_ga_quick_switch_desc"] = "TÜM OYUNCULARIN SİLAH DEĞİŞTİRME SÜRESİ %$speed; AZALIR.",
["menu_cs_gage_assets"] = "GAGE TAKVİYELERİ",
["menu_cs_generating_rewards"] = "GANİMET OLUŞTURULUYOR...",
["menu_cs_get_rewards"] = "ÖDÜLLERİ AL",
["menu_cs_ground_floor"] = "ZEMİN KAT",
["menu_cs_ground_floor_desc"] = "GİRİŞ KATINDA ANA SALON VE DİNLENME ALANI BULUNUYOR. BONNIE, JIRO’NUN KÖŞEDEKİ DİNLENME ALANININ HEMEN YANINA KENDİ KUMARHANESİNİ KURUP KEYFİNİ SÜRMEYE BAŞLADI. JIMMY DE HER ZAMANKİ GİBİ BARDA.$NL;$NL;GARAJDA HOUSTON VE RUST KENDİ PROJELERİ ÜZERİNDE ÇALIŞIYOR. SYDNEY DE ORAYA BİR MASKE BOYAMA ATÖLYESİ KURMUŞ.",
["menu_cs_help_bodhi_1"] = "BODHI, YENİ MEYDAN OKUMALARIN PEŞİNDEN KOŞTUĞU KADAR DALGALARIN DA PEŞİNDEN KOŞAR. SÖRF TAHTALARI YAPMAK, MEDİTASYON YAPMASINA VE OZAKİ 8'İN SINAVLARINA HAZIRLANMASINA YARDIMCI OLUR.",
["menu_cs_help_bodhi_2"] = "BODHI’NİN DALGALARA AŞKI YAPTIĞI TAHTALARDA KENDİNİ GÖSTERİYOR. TAMAMLADIĞI HER TAHTAYLA ZİHİNSEL HAZIRLIĞINDA BİR ADIM DAHA İLERLİYOR.",
["menu_cs_help_bodhi_3"] = "SÖRF TAHTASI YAPIMINDA KUSURSUZLUĞA ULAŞMAK, BODHI’Yİ İHTİYAÇ DUYDUĞU ZİHİN DURUMUNA GETİRDİ. ARTIK ÖNÜNDEKİ ZORLUKLARA HAZIR.",
["menu_cs_help_bonnie_1"] = "BONNIE KENDİ KÜÇÜK KUMARHANESİNİ BURAYA KURMAYI PLANLIYOR. GERÇİ BİRLİKTE OYNAYACAK BİRİNİ BULACAĞININ GARANTİSİ YOK.",
["menu_cs_help_bonnie_2"] = "KOCAMAN VE GÜZEL BİR SLOT MAKİNESİYLE BONNIE BURADA KENDİNİ EVİNDE HİSSETMEYE BAŞLIYOR.",
["menu_cs_help_bonnie_3"] = "BONNIE KÖŞESİNİ SONUNDA TAM İSTEDİĞİ GİBİ DÜZENLEDİ. GERÇEK BİR KRUPİYESİ OLAN KENDİ RULET MASASI BİLE VAR.",
["menu_cs_help_chains_1"] = "CHAINS’İN ÇETENİN SİLAHLARIYLA VE KENDİ ÖZEL PROJELERİYLE UĞRAŞTIĞI ODASI.",
["menu_cs_help_chains_2"] = "CHAINS ARTIK DAHA FAZLA SİLAH İÇİN YERE VE ÇALIŞIRKEN KULLANABİLECEĞİ DAHA İYİ BİR AYDINLATMAYA SAHİP. BURADA HARİKA İŞLER ÇIKACAK.",
["menu_cs_help_chains_3"] = "BURASI KUSURSUZ BİR SİLAHLIK. TÜM WASHINGTON BÖLGESİNİN POLİS GÜCÜNE KARŞI KOYABİLECEK BİR CEPHANELİĞİ SAKLAMAK VE BAKIMINI YAPMAK İÇİN HARİKA.",
["menu_cs_help_clover_1"] = "CLOVER EVİ BASKIN VE SIZMALARDAN KORUYACAK BİR GÜVENLİK SİSTEMİ KURMAYA ÇALIŞIYOR. GÜVENLİ EVİ GERÇEKTEN GÜVENLİ YAPACAK.",
["menu_cs_help_clover_2"] = "CLOVER SONUNDA BURAYA DÜZGÜN BİLGİSAYARLAR YERLEŞTİRDİ. DEDİĞİNE GÖRE GÜVENLİK SİSTEMİ NİHAYET TAŞ DEVRİ’NDEN ÇIKMIŞ.",
["menu_cs_help_clover_3"] = "EV ARTIK KALE GİBİ. HER YERDE KAMERA VAR; CLOVER’IN HABERİ OLMADAN TUVALETE BİLE GİDEMEZSİN.",
["menu_cs_help_common_room_1"] = "MUTFAK, BANYOLAR, GENİŞ BİR SALON... HERKESİN KULLANDIĞI ORTAK ALANLAR.",
["menu_cs_help_common_room_2"] = "DAHA İYİ İMKÂNLAR VE ÇOK DAHA GÜZEL BİR SALON. BURASI GERÇEKTEN İYİ GÖRÜNMEYE BAŞLIYOR.",
["menu_cs_help_common_room_3"] = "ŞIK BANYOLAR, LÜKS BİR SALON VE HİÇ OLMADIĞI KADAR GÜZEL GÖRÜNEN GÖSTERİŞLİ BİR MUTFAK. MİSAFİRLER ETKİLENECEK.",
["menu_cs_help_dallas_1"] = "DALLAS’IN YENİ SOYGUNLAR PLANLAYIP DIŞ DÜNYAYI İZLEDİĞİ KÖŞESİ. BURADAN YAN İŞLERE VE CRIME.NET’E KOLAYCA ERİŞEBİLİR",
["menu_cs_help_dallas_2"] = "KÜÇÜK BİR TELEVİZYONU OLAN DAHA RAHAT BİR ALAN. DALLAS BURANIN PAYDAY GANG İÇİN YARAŞIR BİR KARARGÂHA DÖNÜŞEBİLECEĞİNE İNANMAYA BAŞLIYOR.",
["menu_cs_help_dallas_3"] = "BURASI ARTIK DALLAS İÇİN KUSURSUZ BİR OFİS. SAKİNCE OTURUP YAKLAŞAN SOYGUNLARIN AYRINTILARINI PLANLAMAK İÇİN İHTİYACI OLAN HER ŞEYE SAHİP. ",
["menu_cs_help_dragan_1"] = "CHAINS BAKMAZKEN DRAGAN AYNAYA BİR GÖZ ATTI. BUNDAN SONRA NE OLURSA OLSUN KENDİSİNİ VE ÇETENİN GERİ KALANINI FORMDA TUTACAK. BUNUN İÇİN BİR SPOR SALONU KURUYOR.",
["menu_cs_help_dragan_2"] = "DAHA ÇOK EKİPMAN, DAHA İYİ KASLAR. DRAGAN’IN DEDİĞİNE GÖRE YAŞLANIP AĞARABİLİR AMA ASLA ŞİŞMANLAMAZ.",
["menu_cs_help_dragan_3"] = "TAM DONANIMLI BİR SPOR SALONU VE ÇETENİN TÜM YAKIN DÖVÜŞ SİLAHLARINI DENEMEK İÇİN BİR KUM TORBASI. DRAGAN TAM DA BÖYLE ŞEYLERDEN HOŞLANIR. GEL DE BİRAZ EĞLEN.",
["menu_cs_help_dragon_1"] = "JIRO’NUN SOYGUN ARALARINDA DİNLENİP MEDİTASYON YAPMAYI SEVDİĞİ KÖŞESİ.",
["menu_cs_help_dragon_2"] = "KUM ÇELİĞİNDEN BİR KATANA, BU ODAYA GERÇEKTEN KESKİN BİR HAVA KATIYOR.",
["menu_cs_help_dragon_3"] = "JAPONYA HÂLÂ JIRO’NUN KALBİNDE VE GÜVENLİ EVDEKİ KÖŞESİNDE YAŞIYOR. ESKİ GÜNLERDEN BİRKAÇ SADIK DOSTU, HEM BORÇLARINI ÖDEMEK HEM DE SAYGILARINI GÖSTERMEK İÇİN JIRO’YA KATILIYOR.",
["menu_cs_help_ecp_1"] = "HEVESLİ VİDEO GÜNLÜKÇÜLERİ VE YAYINCILAR ETHAN İLE HİLA’NIN VİDEOLARI İÇİN ALANA İHTİYACI VAR. ALDSTONE’UN ŞİKÂYETLERİNE ALDIRMADAN ORTAK ALANLARA YERLEŞMEYE BAŞLADILAR.",
["menu_cs_help_ecp_2"] = "ETHAN VE HİLA EKİPMANLARINI YERLEŞTİRİP YENİ SETLERİNE ALIŞMAYA BAŞLADI. BAZEN DİĞER SOYGUNCULARIN YOLUNA ÇIKSALAR DA KENDİLERİNİ İFADE EDECEK ALANA İHTİYAÇLARI VAR.",
["menu_cs_help_ecp_3"] = "UYGUN IŞIKLAR VE DÜZENLEMEYLE YENİ KAYIT ALANLARINDA SONUNDA YARATICILIKLARINI TAM KULLANABİLİRLER. HER ŞEY HAZIR OLDUĞUNA GÖRE KAMERA KARŞISINDA NEREDEYSE SOYGUNDA GEÇİRDİKLERİ KADAR VAKİT GEÇİRİYOR GİBİLER.",
["menu_cs_help_houston_1"] = "HOUSTON KAÇIŞ MİNİBÜSÜNDEN VE ÇETENİN ARABALARININ AYARINDAN SORUMLU. ÇETE İHTİYAÇ DUYDUĞUNDA KAÇIŞ MİNİBÜSÜNÜN RENGİNİ DEĞİŞTİREBİLİR.",
["menu_cs_help_houston_2"] = "GARAJ GELİŞTİRİLİYOR, ESKİ ARABA DA ONUNLA BİRLİKTE TOPARLANIYOR. HOUSTON ONA YENİ BİR HAYAT VERİYOR, ARABA DA KARŞILIĞINDA ONA HUZUR SAĞLIYOR.",
["menu_cs_help_houston_3"] = "İÇİNDE KUSURSUZ BİR ARABA OLAN KUSURSUZ BİR GARAJ. BİR DE AHLAKEN KUSURLU AMA TEKNİK AÇIDAN YETENEKLİ TAMİRCİ.",
["menu_cs_help_hoxton_1"] = "HOXTON, ÇETENİN EVRAK VE DOSYALARINI DÜZENE SOKMAYA ÇALIŞIYOR. ORTALIK KARMAKARIŞIK AMA YİNE DE BURADAN FBI DOSYALARINI TAKİP EDİYOR.",
["menu_cs_help_hoxton_2"] = "OFİSTE İŞLER DAHA DÜZENLİ HÂLE GELİYOR. DOSYALAR VE EVRAKLAR ÇOĞUNLUKLA YERLİ YERİNDE. BELLİ Kİ HÂLÂ HAİNİ ARIYOR.",
["menu_cs_help_hoxton_3"] = "HER ŞEYİN YERLİ YERİNDE OLDUĞU TERTEMİZ BİR OFİS. İNANIR MISIN, BUNU HOXTON YAPTI. ALDSTONE ONA İYİ ÖĞRETMİŞ.",
["menu_cs_help_jacket_1"] = "JACKET KONFOR KONUSUNDA ÇOK ŞEY İSTEMİYOR. ESKİ BİR KANEPE VE KASETLERİ KARIŞTIRABİLECEĞİ BİRAZ DONANIM ONA YETER.",
["menu_cs_help_jacket_2"] = "DİLSİZ BİR DELİNİN MEKÂNINDA TELEVİZYON ŞARTTIR. ",
["menu_cs_help_jacket_3"] = "JACKET İÇİN ESKİ BİR ATARİ MAKİNESİ. ARTIK BU ODADAN ÇIKMASI İÇİN HİÇBİR SEBEP YOK. HAYALLERİ GERÇEK OLDU.",
["menu_cs_help_jimmy_1"] = "EVET, JIMMY BARDA. BAŞKA NEREDE OLACAKTI Kİ?",
["menu_cs_help_jimmy_2"] = "BAR ARTIK ÇOK DAHA İYİ STOKLANMIŞ DURUMDA. JIMMY, ALDSTONE’UN DOLDURDUĞU HIZDA BOŞALTMAK İÇİN VAR GÜCÜYLE ÇALIŞIYOR.",
["menu_cs_help_jimmy_3"] = "BAR GENİŞLETİLDİ VE ALDSTONE KALICI BİR BARMEN BULMAYI BAŞARDI. GÖRÜNÜŞE GÖRE JIMMY’YE KATLANMAK ESKİ İŞYERİNİN YANINDA HİÇBİR ŞEYMİŞ.",
["menu_cs_help_jowi_1"] = "ÇETENİN BÜYÜK PLANLARI VAR VE BUNLARI GERÇEKLEŞTİRMEK İÇİN EN BÜYÜK ALANI ALDI.",
["menu_cs_help_jowi_2"] = "YENİ BİR ATIŞ POLİGONU. BECERİLERİ GELİŞTİRME VE SONRAKİ GÖREVE HAZIRLANMA ZAMANI. ÇETE, EĞİTİM EKSİKLİĞİ YÜZÜNDEN YENİLMEYECEK.",
["menu_cs_help_jowi_3"] = "EN İYİ NİŞANCI HAREKET EDERKEN DE HEDEFİNİ VURABİLMELİDİR. ÇETE YENİ REKORLAR KIRIP GEREKTİĞİNDE ANTRENMAN YAPABİLECEĞİ BİR YAKIN MUHAREBE EĞİTİM ALANI KURUYOR.",
["menu_cs_help_joy_1"] = "BİRKAÇ İYİ İŞİN KARŞILIĞINDA LOCKE’UN VERDİĞİ, DOĞU KIYISINDAKİ BİR TELEVİZYON KANALINDAN \"EDİNİLMİŞ\" ÖDÜL. HENÜZ PEK BİR ŞEYE BENZEMİYOR AMA BİRAZ İLGİYLE BU MİNİBÜS BİR BİLGİSAYAR KORSANININ CENNETİNE DÖNÜŞEBİLİR.",
["menu_cs_help_joy_2"] = "ÖNCE YETERİNCE EKRANIN OLDUĞUNDAN EMİN OL. BİR BİLGİSAYAR KORSANI İÇİN MONİTÖRÜN FAZLASI OLMAZ. O KADAR POLİTİKACININ E-POSTASINI KIRDIKTAN SONRA DİNLENECEK ŞIK BİR OTURMA SIRASI DA FENA OLMAZ.",
["menu_cs_help_joy_3"] = "DURMADAN ÇALIŞIP HİÇ OYNAMAMAK JOY’U ÇILGINA ÇEVİRİR. GÜNCEL TÜM OYUN PLATFORMLARINI, HATTA BİRKAÇ ESKİ PLATFORMU DA İÇEREN SEYYAR BİR OYUN İSTASYONUNA GEÇME ZAMANI. YENİ BOYA DA FENA OLMAZ.",
["menu_cs_help_max_1"] = "SANGRES BURAYA YERLEŞMİŞ. BİRASI, KANEPESİ VE KOCAMAN BİR MEKSİKA BAYRAĞI VAR. İNSAN HAYATTAN BAŞKA NE İSTER?",
["menu_cs_help_max_2"] = "SANGRES’İN ARTIK DAHA KALİTELİ EŞYALAR VE DAHA FAZLA BİRAYLA DAHA RAHAT BİR ODASI VAR. ",
["menu_cs_help_max_3"] = "BURASI SANGRES’İN RAHAT YUVASI, MAĞARASI, KALESİ. KUSURSUZ. BİR DE TEKİLA VAR.",
["menu_cs_help_myh_1"] = "DUKE, GÜVENLİ EVDE KENDİNE KUSURSUZ BİR YER BULDU: İKİNCİ KATTAKİ ÇATI ARASI. MANZARALI BİR ODA. ÜSTELİK GÖZLERDEN UZAK!",
["menu_cs_help_myh_2"] = "ARAŞTIRMA YAZILARI, TABLOLAR, KADİM VE GİZEMLİ KÖKENLERE, TABİİ DEĞERE DE SAHİP ESERLER GELMEYE BAŞLADI. DUKE’UN MİTOLOJİYE, TARİHE VE ÇALACAĞI SONRAKİ BÜYÜK ŞEYİN ARAYIŞINA DALMASI İÇİN GEREKEN HER ŞEY VAR.",
["menu_cs_help_myh_3"] = "BAŞKALARI İÇİN GELİŞİGÜZEL KİTAP YIĞINLARI, KÂĞIT ÖBEKLERİ VE ETRAFA KAOTİK BİÇİMDE SAÇILMIŞ ANTİKA IVIR ZIVIRLAR İŞE YARAMAZ BİR DAĞINIKLIKTAN İBARETTİR. DUKE İÇİNSE HER EŞYA, ÇÖZÜLMEYİ BEKLEYEN HARİKA BİR BULMACANIN İPUÇLARINI TAŞIR.",
["menu_cs_help_rust_1"] = "RUST GARAJDA KENDİNİ HEP EVİNDE HİSSETMİŞTİR. BU DA HİÇBİR ZAMAN DEĞİŞMEYECEK.",
["menu_cs_help_rust_2"] = "DAHA İYİ ALETLER, DAHA ÇOK BİRA. DOĞRU YERDEN YAKLAŞIRSAN RUST’I MEMNUN ETMEK KOLAY.",
["menu_cs_help_rust_3"] = "RUST BÜTÜN ALETLERİNİ YERLEŞTİRDİ; SONUNDA KÖŞESİNDE HUZUR İÇİNDE KARA KARA DÜŞÜNEBİLİR.",
["menu_cs_help_sokol_1"] = "SOKOL, SERT ŞUTLARINI FORMDA TUTMAK İÇİN BİR HOKEY SALONU KURUYOR.",
["menu_cs_help_sokol_2"] = "BURASI YAKINDA GERÇEK BİR SAHTE HOKEY PİSTİNE BENZEMEYE BAŞLAYACAK.",
["menu_cs_help_sokol_3"] = "BURASI ARTIK KÜÇÜK BİR BUZ HOKEYİ TAPINAĞI GİBİ. SOKOL KENDİNİ EVİNDE HİSSEDİYOR. HENÜZ KİMSE ONUN REKORUNU GEÇEMEDİ.",
["menu_cs_help_sydney_1"] = "SYDNEY GARAJA BİR MASKE BOYAMA ATÖLYESİ KURDU. ÇETENİN SİLAHLARI İÇİN FARKLI KAPLAMA TASARIMLARINA KOLAYCA GÖZ ATMAK ÜZERE BİR BİLGİSAYAR DA YERLEŞTİRDİ.",
["menu_cs_help_sydney_2"] = "DAHA İYİ ALET VE MALZEMELERLE SYDNEY’NİN ARTIK ÇOK DAHA GÜZEL BİR ÇALIŞMA ALANI VAR. SERGİLEMEK İÇİN DAHA ÇOK MASKE DE KOYABİLİR.",
["menu_cs_help_sydney_3"] = "BİR SANATÇININ ÇALIŞMA ALANI EKSİK HİSSETTİRİRSE ORADA YAPILAN İŞ DE EKSİK KALIR. WASHINGTON’IN EN ŞIK MASKE YAPIM ATÖLYESİ İŞTE BURADA.",
["menu_cs_help_terry_1"] = "SCARFACE MUTFAĞIN YANINA YERLEŞİYOR. TEK DİLEĞİ EVİN DAHA GÜZEL BİR MERDİVENİ OLMASI.",
["menu_cs_help_terry_2"] = "SCARFACE ŞIK YAŞAMAYA ALIŞKIN OLDUĞUNDAN ODASINI GÜZELLEŞTİRMEK İÇİN ÇEŞİTLİ SANAT ESERLERİ TOPLUYOR. GÜZEL BİR HALISI DA VAR.",
["menu_cs_help_terry_3"] = "PİYANO, TAMAM. KAPLAN POSTU, TAMAM. SCARFACE’İN MEKÂNINA HOŞ GELDİN. ŞİMDİ PARANIN KOKUSUNU ALIYOR MUSUN? YOKSA KOKAİNİN Mİ?",
["menu_cs_help_vault_1"] = "ESKİ KASA, ÇETENİN BÜYÜK HEDEFLERİNE YETMEYECEK KADAR KÜÇÜKTÜ.",
["menu_cs_help_vault_2"] = "DAHA BÜYÜĞÜ VE DAHA GÖSTERİŞLİSİ DAHA İYİDİR. ÇETENİN HAKSIZ KAZANÇLARININ GÜVENDE TUTULMASI GEREKİYOR.",
["menu_cs_help_vault_3"] = "BÜYÜK BİR BANKAYA YARAŞIR BİR KASA. YA DA BÜYÜK BANKALARI TEKRAR TEKRAR SOYANLARA.",
["menu_cs_help_wolf_1"] = "WOLF BURADA, SOYGUNLARDA ÇETEYE ÜSTÜNLÜK SAĞLAYACAK YENİ EKİPMANLAR TASARLAYIP ÜRETİYOR.",
["menu_cs_help_wolf_2"] = "DAHA İYİ BİR ÇALIŞMA TEZGÂHI VE DAHA FAZLA ALET ALINDI. ÇILGIN FİKİRLERSE AYNI. BURADAN BİR ŞEYLER ÇIKABİLİR.",
["menu_cs_help_wolf_3"] = "DAHİ BİR MÜHENDİSLE MÜKEMMEL BİR ÇALIŞMA ALANININ KUSURSUZ UYUMUNA TEHLİKELİ BİÇİMDE YAKLAŞIYORUZ. DÜNYA, DİKKAT ET.",
["menu_cs_host_failed"] = "EV SAHİBİ BEKLENİYOR",
["menu_cs_host_failed_text"] = "EV SAHİBİNİN SUÇ SERİSİ BAŞARISIZ OLDU; DEVAM ETMEYİ SEÇMESİ GEREKİYOR.",
["menu_cs_in_progress"] = "SUÇ SERİSİ DEVAM EDİYOR",
["menu_cs_in_progress_desc"] = "SUÇ SERİNE BAŞKA OYUNCULARLA ÇEVRİM İÇİ DEVAM EDEBİLİRSİN AMA ONLARIN SUÇ SERİSİ RÜTBESİNDE, ONLARIN SEÇTİĞİ DEĞİŞTİRİCİLERLE OYNARSIN.$NL;ÇEVRİM İÇİ BİR SUÇ SERİSİNDE BAŞARISIZ OLMAN, KENDİ SUÇ SERİNİN DE BAŞARISIZ OLMASINA YOL AÇAR.",
["menu_cs_in_progress_desc_higher"] = "SUÇ SERİSİ RÜTBEN BU SUÇ SERİSİNİN EV SAHİBİNDEN YÜKSEK. EV SAHİBİNİN SUÇ SERİSİ RÜTBESİ SENİNKİNE EŞİT VEYA DAHA YÜKSEK OLANA KADAR ÖDÜL KAZANAMAZSIN.",
["menu_cs_in_progress_desc_lower"] = "SUÇ SERİSİ RÜTBEN BU SUÇ SERİSİNİN EV SAHİBİNDEN DÜŞÜK. BU EV SAHİBİYLE OYNARKEN EK SUÇ SERİSİ RÜTBELERİ KAZANIRSIN.",
["menu_cs_loot_drops_not_shown"] = "ÜSTELİK $remaining; EK GANİMET ÖDÜLÜ!",
["menu_cs_loot_drops_remaining"] = "KALAN GANİMET ÖDÜLÜ: $loot;",
["menu_cs_map"] = "ODA HARİTASI",
["menu_cs_maximum"] = "AZAMİ",
["menu_cs_mission_complete"] = "GÖREV TAMAMLANDI",
["menu_cs_mission_failed"] = "SUÇ SERİSİ BAŞARISIZ",
["menu_cs_modifier_assault_extender"] = "POLİS SALDIRILARI %$duration; DAHA UZUN SÜRER. BU SÜRE, HER REHİNE VE DÖNÜŞTÜRÜLMÜŞ POLİS İÇİN %$deduction; AZALIR; EN FAZLA $max_hostages; KİŞİ SAYILIR",
["menu_cs_modifier_civs"] = "$count; SİVİLDEN FAZLASI ÖLDÜRÜLÜRSE ALARM ÇALAR.",
["menu_cs_modifier_cloaker_arrest"] = "BAŞARILI BİR HÜCUM GERÇEKLEŞTİREN CLOAKER BİRİMLERİ ARTIK OYUNCUYU YERE DÜŞÜRMEK YERİNE KELEPÇELER.",
["menu_cs_modifier_cloaker_smoke"] = "CLOAKER BİRİMLERİ BİR OYUNCUYA TEKME ATTIĞINDA SİS BOMBASI BIRAKIR.",
["menu_cs_modifier_cloaker_tear_gas"] = "ÖLDÜRÜLEN CLOAKER BİRİMLERİ ANINDA GÖZ YAŞARTICI GAZ BOMBASI BIRAKIR. GAZ $duration; SANİYE SÜRER, $diameter; METRE ÇAPINDA BİR ALANI KAPLAR VE İÇİNDE KALAN SOYGUNCULARA SANİYEDE $damage; HASAR VERİR.",
["menu_cs_modifier_concealment"] = "GİZLİLİKTE ASGARİ GİZLENEBİLİRLİK SEVİYESİ $conceal; ARTAR.",
["menu_cs_modifier_dozer_immune"] = "BULLDOZER BİRİMLERİ PATLAYICI HASARINA KARŞI BAĞIŞIKTIR.",
["menu_cs_modifier_dozer_lmg"] = "ARTIK SKULLDOZER BİRİMLERİ ORTAYA ÇIKAR.",
["menu_cs_modifier_dozer_medic"] = "BİR BULLDOZER ORTAYA ÇIKTIĞINDA MEDIC BULLDOZER OLMA İHTİMALİ VARDIR. MEDIC BULLDOZER HEM MEDIC HEM DE BULLDOZER SAYILIR.",
["menu_cs_modifier_dozer_minigun"] = "BİR BULLDOZER ORTAYA ÇIKTIĞINDA, YAVAŞ HAREKET EDEN VE MİNİGUN KULLANAN BİR BULLDOZER OLMA İHTİMALİ VARDIR.",
["menu_cs_modifier_dozer_rage"] = "BULLDOZER’IN YÜZ PLAKASI KIRILDIĞINDA BULLDOZER ÇILGINCA ÖFKELENİR; TABAN HASARI %$damage; ARTAR.",
["menu_cs_modifier_dozers"] = "BÖLÜMDE AYNI ANDA İKİ EK BULLDOZER BULUNABİLİR.",
["menu_cs_modifier_enemy_damage"] = "DÜŞMANLAR EK OLARAK %$damage; DAHA FAZLA HASAR VERİR.",
["menu_cs_modifier_enemy_health"] = "DÜŞMANLARIN SAĞLIĞI EK OLARAK %$health; ARTAR.",
["menu_cs_modifier_enemy_health_damage"] = "DÜŞMANLARIN SAĞLIĞI EK OLARAK %$health; ARTAR VE EK OLARAK %$damage; DAHA FAZLA HASAR VERİRLER.",
["menu_cs_modifier_health_damage_total"] = "(TOPLAM: %$health; DAHA FAZLA SAĞLIK, %$damage; DAHA FAZLA HASAR.)",
["menu_cs_modifier_heavies"] = "TÜM FBI SWAT BİRİMLERİ AĞIR SWAT BİRİMLERİYLE DEĞİŞTİRİLİR.",
["menu_cs_modifier_heavy_sniper"] = "ORTAYA ÇIKAN HER AĞIR SWAT BİRİMİNİN ZEAL AĞIR SWAT NİŞANCISIYLA DEĞİŞTİRİLME İHTİMALİ VARDIR.",
["menu_cs_modifier_medic_adrenaline"] = "BİR MEDIC BAŞKA BİR POLİSİ CANLANDIRDIĞINDA, CANLANAN POLİSİN TABAN HASARI %$damage; ARTAR.",
["menu_cs_modifier_medic_deathwish"] = "BİR MEDIC ÖLDÜRÜLDÜĞÜNDE, MEDIC’İN İYİLEŞTİRME MENZİLİNDEKİ TÜM POLİSLER ANINDA İYİLEŞİR.",
["menu_cs_modifier_medic_rage"] = "MEDIC’İN İYİLEŞTİRME MENZİLİNDE ÖLEN HER POLİS İÇİN O MEDIC’İN TABAN HASARI %$damage; ARTAR. BU ETKİ SINIRSIZ BİRİKİR.",
["menu_cs_modifier_medic_speed"] = "MEDIC BİRİMLERİNİN İYİLEŞTİRME BEKLEME SÜRESİ %$speed; DAHA HIZLI DOLAR.",
["menu_cs_modifier_medics"] = "BÖLÜMDE AYNI ANDA İKİ EK MEDIC BULUNABİLİR.",
["menu_cs_modifier_no_hurt"] = "DÜŞMANLAR HASAR ALDIKLARINDA SENDELEMEZ.",
["menu_cs_modifier_pagers"] = "HER SOYGUNDA $count; DAHA AZ ÇAĞRI CİHAZINA CEVAP VERİLEBİLİR.",
["menu_cs_modifier_shield_phalanx"] = "OYUNDAKİ TÜM SHIELD BİRİMLERİ, CAPTAİN WİNTER’IN SHIELD BİRİMLERİYLE DEĞİŞTİRİLİR.",
["menu_cs_modifier_shield_reflect"] = "SHIELD BİRİMLERİ MERMİLERİ GERİ SEKTİRİR.",
["menu_cs_modifier_taser_overcharge"] = "TASER’IN ELEKTRİKLE BAYILTMA ETKİSİ ARTIK OYUNCUYU %$speed; DAHA HIZLI BAYILTIR.",
