["menu_cs_modifiers_forced"] = "ZORUNLU DEĞİŞTİRİCİLER",
["menu_cs_modifiers_forced_multiple"] = "SUÇ SERİSİNE $count; DEĞİŞTİRİCİ EKLENDİ",
["menu_cs_modifiers_forced_single"] = "SUÇ SERİSİNE BİR DEĞİŞTİRİCİ EKLENDİ",
["menu_cs_modifiers_has_failed"] = "SUÇ SERİSİ BAŞARISIZ",
["menu_cs_modifiers_has_failed_desc"] = "DEVAM EDENE KADAR RÜTBE VEYA ÖDÜL KAZANAMAZSIN.",
["menu_cs_modifiers_loud"] = "ÇATIŞMA DEĞİŞTİRİCİLERİ",
["menu_cs_modifiers_not_in_progress"] = "DEVAM EDEN SUÇ SERİSİ YOK",
["menu_cs_modifiers_not_in_progress_desc"] = "RÜTBE VE ÖDÜL KAZANMAK İÇİN KENDİ SUÇ SERİNİ BAŞLAT.",
["menu_cs_modifiers_stealth"] = "GİZLİLİK DEĞİŞTİRİCİLERİ",
["menu_cs_modifiers_suspended"] = "SUÇ SERİSİ ASKIYA ALINDI",
["menu_cs_modifiers_suspended_desc"] = "EV SAHİBİNİN SUÇ SERİSİ RÜTBESİ SENİNKİNE EŞİT VEYA DAHA YÜKSEK OLANA KADAR RÜTBE VEYA ÖDÜL KAZANAMAZSIN.",
